[{"path":"src/LearningLibrary.tsx","content":"import { useLayoutEffect, useRef, useState } from "react";
import { learningGroups, learningPrompts, type LearningSkill } from "./content/learning";
import { navigate } from "./navigation";
import { PromptDialog } from "./PromptDialog";
import { Icon } from "./Icon";
import { learningPromptText } from "./prompt-text";
import { RecentList } from "./QuickAccess";
import type { ClipboardWriter } from "./clipboard-writer";
import type { RecentPrompt } from "./shortcuts";
import "./learning-library.css";
import type { Locale } from "./types";

interface Props {
  locale: Locale;
  promptId: string | null;
  copying: boolean;
  writer: ClipboardWriter;
  favorites: string[];
  recent: RecentPrompt[];
  onFavorite: (id: string) => void;
  onDelivered: (id: string) => Promise<boolean>;
}

export function LearningLibrary({ locale, promptId, copying, writer, favorites, recent, onFavorite, onDelivered }: Props) {
  const en = locale === "en";
  const selected = learningPrompts.find((p) => p.id === promptId);
  const [skill, setSkill] = useState<LearningSkill>(selected?.skill ?? "listening");
  const [copied, setCopied] = useState(false);
  const [manual, setManual] = useState(false);
  const [message, setMessage] = useState("");
  const [savedOnly, setSavedOnly] = useState(false);
  const text = useRef<HTMLTextAreaElement>(null);
  const group = learningGroups.find((item) => item.id === skill)!;
  const visiblePrompts = learningPrompts.filter((p) => p.skill === skill && (!savedOnly || favorites.includes(p.id)));

  useLayoutEffect(() => {
    if (selected) setSkill(selected.skill);
  }, [selected]);
  useLayoutEffect(() => {
    writer.invalidate();
    setCopied(false);
    setManual(false);
    setMessage("");
    return () => { writer.invalidate(); };
  }, [promptId, locale, writer]);
  useLayoutEffect(() => {
    if (manual) {
      text.current?.focus();
      text.current?.select();
    }
  }, [manual]);

  const close = () => {
    writer.invalidate();
    if (history.state?.talksproutLearningPrompt === promptId) history.back();
    else navigate("#learning");
  };
  const copy = async () => {
    if (!selected || copying) return;
    setCopied(false);
    setManual(false);
    setMessage("");
    let persisted = true;
    await writer.write({
      text: learningPromptText(selected, locale),
      onDelivered: async () => { persisted = await onDelivered(selected.id); },
      onSuccess: () => {
        setCopied(true);
        setMessage((en ? "Copied! Paste into your AI with the material." : "已复制！粘贴到常用 AI，并提供相关材料。") +
          (persisted ? "" : en ? " Recent history could not be saved on this device." : " 最近复制记录未能保存在本机。"));
      },
      onFailure: () => {
        setManual(true);
        setMessage(en ? "Copy unavailable. Select and copy the prompt manually." : "自动复制不可用，请手动复制已选中的提示词。");
      },
    });
  };

  return (
    <section className="learning-library" aria-label={en ? "Extra learning prompts" : "辅助学习提示词"}>
      <p className="view-caption">
        {en ? "Something hard to follow or put into words? Pick a task and take it to your AI." : "听不懂、读不透、写不顺？选一个需求，带去常用 AI。"}
      </p>
      <div className="learning-directions" role="group" aria-label={en ? "Learning direction" : "学习方向"}>
        {learningGroups.map((item) => (
          <button
            key={item.id}
            aria-pressed={skill === item.id}
            onClick={() => setSkill(item.id)}
          >
            <span className="direction-emoji" aria-hidden="true">{item.emoji}</span>
            <strong>{item.title[locale]}</strong>
          </button>
        ))}
      </div>
      <RecentList items={recent} locale={locale} />
      <button className="learning-saved-filter" aria-label={en ? "Saved only" : "只看收藏"} aria-pressed={savedOnly} onClick={() => setSavedOnly(!savedOnly)}>
        <Icon name="heart" />{en ? "Saved only" : "只看收藏"}
      </button>
      <section className={`learning-group learning-${skill}`} aria-labelledby="learning-group-title">
        <div className="learning-group-heading">
          <h2 className="section-label" id="learning-group-title">{group.title[locale]}</h2>
          <span>{en ? `${visiblePrompts.length} prompts` : `${visiblePrompts.length} 个提示词`}</span>
        </div>
        <p className="learning-group-description">{group.description[locale]}</p>
        <div className="native-list learning-list">
          {visiblePrompts.length === 0 && <p className="learning-empty">{en ? "No saved prompts in this direction yet." : "这个方向还没有收藏的提示词。"}</p>}
          {visiblePrompts.map((p) => (
            <div className="learning-prompt-row" key={p.id}>
            <button
              className="learning-prompt"
              key={p.id}
              data-learning-prompt={p.id}
              onClick={() => navigate(`#learning?prompt=${p.id}`, { talksproutLearningPrompt: p.id })}
            >
              <span className="learning-prompt-emoji" aria-hidden="true">{p.emoji}</span>
              <span className="learning-prompt-text">
                <strong>{p.title[locale]}</strong>
                <small>{p.description[locale]}</small>
                <span className="learning-examples">{p.examples[locale]}</span>
              </span>
              <Icon name="chevron" />
            </button>
            <button className="learning-favorite icon-button" aria-label={`${favorites.includes(p.id) ? (en ? "Unsave" : "取消收藏") : (en ? "Save" : "收藏")}：${p.title[locale]}`} aria-pressed={favorites.includes(p.id)} onClick={() => onFavorite(p.id)}>
              <Icon name="heart" />
            </button>
            </div>
          ))}
        </div>
      </section>
      <p className="section-note">{en ? "Copy → paste into your AI → provide the material there. No uploads needed here." : "复制 → 粘贴给 AI → 在那里提供材料，这里无需上传。"}</p>
      {selected && (
        <PromptDialog
          key={selected.id}
          locale={locale}
          prompt={null}
          message=""
          manual={false}
          copied={false}
          copying={false}
          onClose={close}
          onCopy={() => {}}
          content={<>
            <h2 id="dialog-title" className="learning-detail-title">
              <span aria-hidden="true">{selected.emoji}</span>{selected.title[locale]}
            </h2>
            <p>{selected.description[locale]}</p>
            <p className="learning-detail-examples">{selected.examples[locale]}</p>
            <p className="requirement"><strong>{en ? "Preparation: " : "准备："}</strong>{selected.preparation[locale]}</p>
            <p>{selected.guide[locale]}</p>
            <label htmlFor="prompt-text">{en ? "English prompt" : "英文提示词"}</label>
            <textarea id="prompt-text" ref={text} value={learningPromptText(selected, locale)} readOnly lang="en" spellCheck={false} />
          </>}
          footer={<footer className="sheet-footer">
            <button className="primary modal-copy learning-copy" disabled={copying} aria-busy={copying} onClick={() => void copy()}>
              <Icon name="copy" />
              {copying ? (en ? "Copying…" : "正在复制…") : copied ? (en ? "Copied ✓" : "已复制 ✓") : (en ? "Copy prompt" : "复制提示词")}
            </button>
            <p role={manual ? "alert" : "status"} aria-live="polite" className={manual ? "manual-note" : ""}>{message}</p>
          </footer>}
        />
      )}
    </section>
  );
}
"},{"path":"src/PromptCard.tsx","content":"import { dictionary, metadata, type Locale } from "./i18n";
import type { Prompt } from "./types";
import { Icon } from "./Icon";
export function PromptCard({
  prompt: p,
  favorite,
  copying,
  onFavorite,
  onDetail,
  onCopy,
  locale,
}: {
  locale: Locale;
  prompt: Prompt;
  favorite: boolean;
  copying: boolean;
  onFavorite: () => void;
  onDetail: () => void;
  onCopy: () => void;
}) {
  const en = locale === "en",
    t = dictionary[locale];
  return (
    <article className="card">
      <button
        className="detail-link card-main"
        data-detail={p.id}
        onClick={(event) => {
          event.currentTarget.focus({ preventScroll: true });
          onDetail();
        }}
      >
        <span className="prompt-info">
          <span className="prompt-title">
            <h3>{en ? p.english : p.title}</h3>
            {p.kind === "review" && p.recommended && (
              <span className="recommended">{en ? "Recommended" : "推荐"}</span>
            )}
          </span>
          <span className="prompt-description">
            {metadata(p, "description", locale)}
          </span>
          <span className="tags">
            {p.kind !== "review" && <span>{p.level}</span>}
            <span>{metadata(p, "feedback", locale)}</span>
          </span>
        </span>
        <Icon name="chevron" />
      </button>
      <div className="card-actions">
        <button
          className="favorite icon-button"
          data-favorite={p.id}
          aria-label={`${favorite ? (en ? "Remove favorite" : "取消收藏") : en ? "Favorite" : "收藏"}${en ? ": " : "："}${en ? p.english : p.title}`}
          aria-pressed={favorite}
          onClick={onFavorite}
        >
          <Icon name="heart" />
        </button>
        <button
          className="copy icon-button"
          data-copy={p.id}
          disabled={copying}
          aria-busy={copying}
          aria-label={`${t.copy}${en ? ": " : "："}${en ? p.english : p.title}`}
          onClick={(event) => {
            event.currentTarget.focus({ preventScroll: true });
            onCopy();
          }}
        >
          <Icon name="copy" />
        </button>
      </div>
    </article>
  );
}
"},{"path":"src/PromptDialog.tsx","content":"import { useEffect, useRef, type ReactNode } from "react";
import { ScenarioPicker } from "./ScenarioPicker";
import type { SceneSelection } from "./scenes";
import { Icon } from "./Icon";
import { promptText } from "./prompt-text";
import { dictionary, metadata, categoryEnglish, type Locale } from "./i18n";
import type { Prompt, PromptVariant, ReviewSource } from "./types";
export function PromptDialog({
  prompt: p,
  content,
  message,
  manual,
  copied,
  copying,
  onClose,
  onCopy,
  locale,
  variant = "full",
  onVariantChange,
  reviewSource = "current",
  onSourceChange,
  sceneSelection,
  onSceneChange,
  footer,
  practiceActions,
}: {
  footer?: ReactNode;
  practiceActions?: ReactNode;
  sceneSelection?: SceneSelection;
  onSceneChange?: (selection?: SceneSelection) => void;
  locale: Locale;
  prompt: Prompt | null;
  content: ReactNode;
  message: string;
  manual: boolean;
  copied: boolean;
  copying: boolean;
  onClose: () => void;
  onCopy: (p: Prompt, variant: PromptVariant) => void;
  reviewSource?: ReviewSource;
  onSourceChange?: (source: ReviewSource) => void;
  variant?: PromptVariant;
  onVariantChange?: (variant: PromptVariant) => void;
}) {
  const en = locale === "en",
    t = dictionary[locale],
    s = (zh: string, english: string) => (en ? english : zh);
  const reviewing = p?.kind === "review";
  const spokenLabel = reviewing
    ? s("语音结尾提示", "Spoken wrap-up")
    : s("语音开场白", "Spoken opening");
  const selectedText = p ? promptText(p, variant, reviewSource, locale) : "";
  const ref = useRef<HTMLDialogElement>(null);
  const text = useRef<HTMLTextAreaElement>(null);
  useEffect(() => {
    const d = ref.current!;
    const previous = document.activeElement as HTMLElement | null;
    const originBase = location.hash.split("?")[0];
    d.showModal();
    return () => {
      d.close();
      requestAnimationFrame(() => {
        if (document.querySelector("dialog[open]") || location.hash.split("?")[0] !== originBase) return;
        const focused = document.activeElement;
        if (focused !== document.body && focused?.isConnected && focused !== previous) return;
        if (previous?.isConnected) previous.focus({ preventScroll: true });
        else
          document
            .querySelector<HTMLElement>("#library-heading")
            ?.focus({ preventScroll: true });
      });
    };
  }, []);
  useEffect(() => {
    if (manual) {
      text.current?.focus();
      text.current?.select();
    }
  }, [manual, p, variant, reviewSource]);
  return (
    <dialog
      id="detail"
      className="prompt-sheet"
      ref={ref}
      aria-labelledby="dialog-title"
      onCancel={(event) => {
        event.preventDefault();
        onClose();
      }}
      onClick={(e) => {
        if (e.target !== e.currentTarget) return;
        const r = e.currentTarget.getBoundingClientRect();
        if (
          e.clientX < r.left ||
          e.clientX > r.right ||
          e.clientY < r.top ||
          e.clientY > r.bottom
        )
          onClose();
      }}
    >
      <header className="sheet-toolbar">
        {p ? (
          <div>
            <div className="eyebrow">
              {en ? categoryEnglish[p.category] : p.category}
              {p.kind !== "review" && ` · ${p.level}`}
            </div>
            <h2 id="dialog-title">{en ? p.english : p.title}</h2>
          </div>
        ) : (
          <span className="sheet-brand">TalkSprout</span>
        )}
        <button
          className="modal-close icon-button"
          aria-label={t.close}
          onClick={onClose}
        >
          <Icon name="close" />
        </button>
      </header>
      <div className="sheet-content">
        {p ? (
          <>
            {!en && <p className="english-title">{p.english}</p>}
            {onSceneChange && (
              <ScenarioPicker
                key={p.id}
                prompt={p}
                locale={locale}
                selection={sceneSelection}
                onChange={onSceneChange}
              />
            )}
            {practiceActions}
            <div
              className="prompt-formats"
              role="tablist"
              aria-label={s("使用方式", "Prompt format")}
              onKeyDown={(event) => {
                let next: PromptVariant;
                if (event.key === "Home") next = "full";
                else if (event.key === "End") next = "spoken";
                else if (
                  event.key === "ArrowRight" ||
                  event.key === "ArrowLeft"
                )
                  next = variant === "full" ? "spoken" : "full";
                else return;
                event.preventDefault();
                onVariantChange?.(next);
                document.getElementById(`format-${next}`)?.focus();
              }}
            >
              <button
                role="tab"
                id="format-full"
                tabIndex={variant === "full" ? 0 : -1}
                aria-selected={variant === "full"}
                aria-controls="prompt-panel"
                onClick={() => onVariantChange?.("full")}
              >
                {s("完整提示词", "Full prompt")}
              </button>
              <button
                role="tab"
                id="format-spoken"
                tabIndex={variant === "spoken" ? 0 : -1}
                aria-selected={variant === "spoken"}
                aria-controls="prompt-panel"
                onClick={() => onVariantChange?.("spoken")}
              >
                {spokenLabel}
              </button>
            </div>
            <section
              id="prompt-panel"
              role="tabpanel"
              aria-labelledby={
                variant === "spoken" ? "format-spoken" : "format-full"
              }
            >
              {variant === "full" ? (
                <>
                  <p>{metadata(p, "description", locale)}</p>
                  <div className="modal-facts">
                    {p.kind !== "review" && (
                      <span>
                        {s("建议 ", "Suggested ")}
                        {p.minutes}
                        {s(" 分钟", " min")}
                      </span>
                    )}
                    <span>{metadata(p, "feedback", locale)}</span>
                  </div>
                  <details className="usage-guide">
                    <summary>
                      {reviewing
                        ? s("怎么用", "How to use")
                        : s("怎么练", "How to practice")}
                    </summary>
                    <p>{metadata(p, "guide", locale)}</p>
                    <p className="requirement">
                      {s("准备：", "Preparation: ")}
                      {metadata(p, "requires", locale)}
                    </p>
                  </details>
                </>
              ) : (
                <>
                  <p>
                    {reviewing
                      ? s(
                          "聊天结束时，在原来的 AI 语音对话里念下面这段英文。优先请求书面材料；只能语音回复时，改为简短口头复盘。",
                          "Read this in your existing AI voice chat when practice ends. Request written material if available; otherwise, use a brief spoken recap.",
                        )
                      : s(
                          "不方便粘贴时，在 AI 语音对话开始时照着念下面这段英文，念完后等 AI 提问。",
                          "If you cannot paste text, read this aloud at the start of your AI voice conversation, then let the AI begin.",
                        )}
                  </p>
                  <p className="spoken-duration">
                    {s("朗读约 ", "About ")}
                    {Math.ceil(
                      ((selectedText.trim().split(/\s+/).length / 140) * 60) /
                        5,
                    ) * 5}
                    –
                    {Math.ceil(
                      ((selectedText.trim().split(/\s+/).length / 100) * 60) /
                        5,
                    ) * 5}
                    {s(
                      " 秒，因语速而异",
                      " seconds to read, depending on pace",
                    )}
                  </p>
                </>
              )}
              {reviewing && variant === "full" && (
                <div className="review-source">
                  <label htmlFor="review-source">
                    {s("整理哪段聊天", "Conversation source")}
                  </label>
                  <select
                    id="review-source"
                    value={reviewSource}
                    onChange={(event) =>
                      onSourceChange?.(event.target.value as ReviewSource)
                    }
                  >
                    <option value="current">
                      {s("当前 AI 聊天", "Current AI chat")}
                    </option>
                    <option value="transcript">
                      {s("其他聊天记录", "Another transcript")}
                    </option>
                  </select>
                  <p>
                    {reviewSource === "transcript"
                      ? s(
                          "复制后，先将模板末尾的占位文字替换为聊天记录（注明说话人），再发给 AI。本站不读取聊天记录。",
                          "After copying, replace the placeholder at the end with a speaker-labeled transcript before sending. This site does not read your conversations.",
                        )
                      : s(
                          "在原来的 AI 聊天中发送。AI 只能整理它当前能读取的内容，无法找回已丢失的上下文。",
                          "Send in your original AI chat. The AI can review only the context it still has access to.",
                        )}
                  </p>
                </div>
              )}
              {variant === "full" || manual ? (
                <>
                  <label htmlFor="prompt-text">
                    {variant === "spoken"
                      ? spokenLabel
                      : s("完整英文提示词", "Full English prompt")}
                  </label>
                  <textarea
                    id="prompt-text"
                    ref={text}
                    readOnly
                    lang="en"
                    spellCheck={false}
                    value={selectedText}
                  />
                </>
              ) : (
                <div
                  className="spoken-script"
                  lang="en"
                  aria-label={spokenLabel}
                >
                  {selectedText.split("\n").map((sentence, i) => (
                    <p key={i}>{sentence}</p>
                  ))}
                </div>
              )}
            </section>
            <p className="fineprint">
              {reviewing
                ? s(
                    "在已有对话结束后使用。本站只提供提示词，不接收或保存 AI 聊天。",
                    "Use after an existing conversation. This site provides prompts; it does not receive or store AI chats.",
                  )
                : variant === "spoken"
                  ? s(
                      "在 AI 语音对话开始时，照着上面的英文念一遍，再等待 AI 回应。",
                      "Read the English opening aloud when your AI voice conversation starts, then wait for its reply.",
                    )
                  : s(
                      "粘贴到常用 AI，按练习模式开启语音或文字对话。本站不接收或保存 AI 聊天。",
                      "Paste into your AI and start by voice or text. This site does not store AI conversations.",
                    )}
            </p>
            {!reviewing && (
              <details className="chat-tips">
                <summary>
                  {s(
                    "和 AI 聊天时，可以这样说",
                    "Things you can say to your AI",
                  )}
                </summary>
                <p>
                  {s(
                    "开始练习后，在你使用的 AI 聊天里，直接用英文说：",
                    "Once practice starts, say these phrases in your AI chat:",
                  )}
                </p>
                <dl>
                  <div>
                    <dt lang="en">Help, please.</dt>
                    <dd>
                      {s(
                        "不知道怎么表达时，请 AI 给一个英文示例或简短提示。",
                        "Ask for a short hint or an English example when you get stuck.",
                      )}
                    </dd>
                  </div>
                  <div>
                    <dt lang="en">Review, please.</dt>
                    <dd>
                      {s(
                        "请 AI 回顾刚才练过的表达和需要改进的地方。",
                        "Ask the AI to recap expressions you practiced and useful improvements.",
                      )}
                    </dd>
                  </div>
                  <div>
                    <dt lang="en">Let's finish.</dt>
                    <dd>
                      {s(
                        "告诉 AI 今天先聊到这里，请它做一个简短总结。",
                        "Tell the AI you want to stop and get a short summary.",
                      )}
                    </dd>
                  </div>
                </dl>
              </details>
            )}
          </>
        ) : (
          content
        )}
      </div>
      {footer}
      {p && (
        <footer className="sheet-footer">
          {" "}
          <button
            className="primary modal-copy"
            data-copy={p.id}
            data-variant={variant}
            disabled={copying}
            aria-busy={copying}
            onClick={() => onCopy(p, variant)}
          >
            {copying
              ? s("正在复制…", "Copying…")
              : copied && !manual
                ? s("已复制 ✓", "Copied ✓")
                : variant === "spoken"
                  ? reviewing
                    ? s("复制语音结尾提示", "Copy spoken wrap-up")
                    : s("复制语音开场白", "Copy spoken opening")
                  : s("复制完整提示词", "Copy full prompt")}
          </button>
          <p
            role={manual ? "alert" : "status"}
            aria-live="polite"
            className={manual ? "manual-note" : ""}
          >
            {message}
          </p>
        </footer>
      )}
    </dialog>
  );
}
"},{"path":"src/PromptLibrary.tsx","content":"import { useState, type ReactNode } from "react";
import { collections, reviewCollection } from "./content/collections";
import { allPrompts } from "./prompts";
import { filterPrompts } from "./library";
import { PromptCard } from "./PromptCard";
import { Icon } from "./Icon";
import { navigate } from "./navigation";
import type { Prompt, Locale } from "./types";

type Purpose = "practice" | "review";
type Props = {
  homeExtras?: ReactNode;
  reviewExtras?: ReactNode;
  locale: Locale;
  purpose: Purpose;
  collection: string | null;
  favorites: string[];
  copying: boolean;
  onFavorite: (id: string) => void;
  onDetail: (prompt: Prompt) => void;
  onCopy: (prompt: Prompt) => void;
};
export function PromptLibrary({
  locale,
  purpose,
  collection,
  favorites,
  copying,
  onFavorite,
  onDetail,
  onCopy,
  homeExtras,
  reviewExtras,
}: Props) {
  const en = locale === "en";
  const reviewing = purpose === "review";
  const filterKey = reviewing ? "review" : (collection ?? "practice");
  const [filters, setFilters] = useState<
    Record<string, { query: string; favoritesOnly: boolean }>
  >({});
  const { query, favoritesOnly } = filters[filterKey] ?? {
    query: "",
    favoritesOnly: false,
  };
  const update = (changes: { query?: string; favoritesOnly?: boolean }) =>
    setFilters((old) => ({
      ...old,
      [filterKey]: {
        ...(old[filterKey] ?? { query: "", favoritesOnly: false }),
        ...changes,
      },
    }));
  const clear = () => update({ query: "", favoritesOnly: false });
  const current = collections.find((c) => c.id === collection);
  const stagePrompts = allPrompts.filter(
    (p) =>
      (p.kind === "review") === reviewing &&
      (!current || reviewing || p.category === current.category),
  );
  const searching = !!query.trim() || favoritesOnly;
  const matches = filterPrompts(stagePrompts, {
    query,
    favoritesOnly,
    favorites,
  });
  const groups = reviewing
    ? [reviewCollection]
    : collections.filter((c) => (collection ? c.id === collection : searching));
  const showCollections = !reviewing && !current && !searching;
  const searchLabel = reviewing
    ? en
      ? "Search reviews"
      : "搜索复习方式"
    : en
      ? "Search coaches"
      : "搜索陪练模式";
  return (
    <section
      id="library"
      className="library-view"
      aria-label={en ? "Prompt library" : "提示词目录"}
    >
      <p className="view-caption">
        {reviewing
          ? en
            ? "Save what you learned from your AI conversation."
            : "聊天结束后，把学到的表达留下来。"
          : current
            ? en
              ? current.descriptionEn
              : current.description
            : en
              ? "Choose how you want to learn as you chat."
              : "选一种陪练方式，随聊随学。"}
      </p>
      <div className="library-toolbar">
        <label className="search">
          <Icon name="search" />
          <input
            id="search"
            type="search"
            aria-label={searchLabel}
            placeholder={searchLabel}
            value={query}
            onChange={(e) => update({ query: e.target.value })}
          />
        </label>
        <button
          id="favorites"
          aria-label={en ? "Saved" : "收藏"}
          className="favorites-filter"
          aria-pressed={favoritesOnly}
          onClick={() => update({ favoritesOnly: !favoritesOnly })}
        >
          <Icon name="heart" />
        </button>
      </div>
      {searching && (
        <div className="results-toolbar">
          <p role="status">
            {matches.length} {en ? "results" : "个结果"}
          </p>
          <button onClick={clear}>{en ? "Clear filters" : "清除筛选"}</button>
        </div>
      )}
      {showCollections ? (
        <>
          {homeExtras}
          <h2 className="section-label">
            {en ? "Practice collections" : "练习分类"}
          </h2>
          <div className="collection-grid native-list">
            {collections.map((c, index) => (
              <button
                className="collection-card"
                key={c.id}
                data-collection={c.id}
                onClick={() => {
                  clear();
                  navigate(`#collection/${c.id}`);
                }}
              >
                <span className={`entry-icon tone-${index + 1}`}>
                  <Icon
                    name={index === 0 ? "chat" : index === 1 ? "game" : "image"}
                  />
                </span>
                <span className="collection-text">
                  <strong>{en ? c.titleEn : c.category}</strong>
                  <span>{en ? c.descriptionEn : c.description}</span>
                </span>
                <span className="collection-count">
                  {allPrompts.filter((p) => p.category === c.category).length}
                </span>
                <Icon name="chevron" />
              </button>
            ))}
          </div>
          <p className="section-note">
            {en
              ? "Copy a prompt to your AI, or read its short spoken opening aloud."
              : "复制给常用 AI，或照着简短语音开场白念。"}
          </p>
          <div className="learning-entry">
            <button onClick={() => navigate("#learning")}>
              <Icon name="book" />
              <span>
                <strong>{en ? "Listening, reading & writing" : "听读写辅助"}</strong>
                <small>{en ? "Extra prompts for your other English practice." : "为其他英语学习需求，补充几个实用提示词。"}</small>
              </span>
              <Icon name="chevron" />
            </button>
          </div>
        </>
      ) : (
        <>
          {reviewing && !searching && reviewExtras}
          {reviewing && !searching && (
            <p className="review-recommendation">
              {en
                ? "Start with Complete Study Notes, or focus on one thing below."
                : "先用「完整学习笔记」，也可以只整理其中一项。"}
            </p>
          )}
          {groups.map((c) => {
            const list = matches.filter((p) => p.category === c.category);
            if (!list.length) return null;
            return (
              <section
                key={c.id}
                className="collection-results"
                aria-label={en ? c.titleEn : c.category}
              >
                {searching && (
                  <h2 className="section-label">
                    {en ? c.titleEn : c.category}
                  </h2>
                )}
                <div className="cards native-list">
                  {list.map((p) => (
                    <PromptCard
                      key={p.id}
                      prompt={p}
                      locale={locale}
                      favorite={favorites.includes(p.id)}
                      copying={copying}
                      onFavorite={() => onFavorite(p.id)}
                      onDetail={() => onDetail(p)}
                      onCopy={() => onCopy(p)}
                    />
                  ))}
                </div>
              </section>
            );
          })}
          {!matches.some((p) =>
            groups.some((c) => c.category === p.category),
          ) && (
            <div className="empty">
              <span className="empty-icon">
                <Icon name={favoritesOnly ? "heart" : "search"} />
              </span>
              <h2>
                {favoritesOnly
                  ? en
                    ? "Nothing saved here yet"
                    : "这里还没有收藏"
                  : en
                    ? "No matching prompts"
                    : "没有找到匹配内容"}
              </h2>
              <p>
                {favoritesOnly
                  ? en
                    ? "Tap a heart beside a prompt to save it here."
                    : "点提示词旁的爱心，即可收藏。"
                  : en
                    ? "Try another word or clear your filters."
                    : "换个关键词，或清除筛选。"}
              </p>
            </div>
          )}
        </>
      )}
    </section>
  );
}
"},{"path":"src/ScenarioPicker.tsx","content":"import { useEffect, useRef, useState } from "react";
import { compatibleScenes, type SceneSelection } from "./scenes";
import { prompts } from "./prompts";
import { SceneBrowser } from "./SceneBrowser";
import { sceneIcon } from "./scene-icons";
import type { Locale, Prompt } from "./types";

export function ScenarioPicker({
  prompt,
  locale,
  selection,
  onChange,
}: {
  prompt: Prompt;
  locale: Locale;
  selection?: SceneSelection;
  onChange: (next?: SceneSelection) => void;
}) {
  const trigger = useRef<HTMLButtonElement>(null);
  const [browsing, setBrowsing] = useState(
    () =>
      history.state?.talksproutSceneCoach === prompt.id &&
      typeof history.state?.talksproutSceneBrowser === "string",
  );
  useEffect(() => {
    const restore = () =>
      setBrowsing(
        history.state?.talksproutSceneCoach === prompt.id &&
          typeof history.state?.talksproutSceneBrowser === "string",
      );
    window.addEventListener("popstate", restore);
    return () => window.removeEventListener("popstate", restore);
  }, [prompt.id]);
  const available = compatibleScenes(prompt);
  const selected = available.find((scene) => scene.id === selection?.sceneId);
  if (!available.length) return null;
  const en = locale === "en";
  const s = (zh: string, english: string) => (en ? english : zh);
  const selectedLabel = selected?.title[locale] ?? s("不指定场景", "No preset");
  return (
    <section
      className="scenario-picker"
      aria-label={s("练习场景", "Practice scenario")}
    >
      <button
        type="button"
        className="scene-trigger"
        ref={trigger}
        aria-label={`${s("练习场景", "Practice scenario")}：${selectedLabel}`}
        aria-haspopup="dialog"
        aria-expanded={browsing}
        onClick={() => setBrowsing(true)}
      >
        <span className="scene-emoji" aria-hidden="true">
          {selected ? sceneIcon(selected) : "💬"}
        </span>
        <span className="scene-row-copy">
          <small>{s("练习场景", "Practice scenario")}</small>
          <strong>{selectedLabel}</strong>
        </span>
        <span className="scene-chevron" aria-hidden="true">
          ›
        </span>
      </button>
      {selected && selection && (
        <details className="scene-settings" key={selected.id}>
          <summary>{s("场景设置", "Scenario settings")}</summary>
          <div className="scene-settings-body">
            <p lang="en">{selected.context}</p>
            <p lang="en">{selected.goal}</p>
            <p className="fineprint">
              {s("模拟练习 · 推荐：", "Hypothetical practice · Recommended: ")}
              {selected.recommendedCoachIds
                .map((id) => {
                  const coach = prompts.find((p) => p.id === id)!;
                  return en ? coach.english : coach.title;
                })
                .join(" · ")}
              {selected.handbookUnit &&
                ` · ${s("手册单元", "Handbook unit")} ${selected.handbookUnit}`}
            </p>
            <label htmlFor="scene-background">
              {s("补充背景（可选）", "Additional background (optional)")}
            </label>
            <textarea
              id="scene-background"
              rows={3}
              maxLength={2000}
              value={selection.background}
              onChange={(e) =>
                onChange({ ...selection, background: e.target.value })
              }
              placeholder={s(
                "例如：我主要写 Go，想练习解释并发。",
                "For example: I use Go and want to explain concurrency.",
              )}
            />
            <p className="fineprint">
              {s(
                "仅加入完整提示词，不在本机保存。语音版保留主题，详细背景可在对话中补充。",
                "Included only in the full prompt; not saved locally. Add details during the spoken conversation.",
              )}
            </p>
            {selected.category === "interview" &&
              prompt.id === "roleplay-coach" && (
                <fieldset className="scene-pace">
                  <legend>{s("面试节奏", "Interview pace")}</legend>
                  <div>
                    <button
                      type="button"
                      aria-pressed={selection.pace === "coached"}
                      onClick={() =>
                        onChange({ ...selection, pace: "coached" })
                      }
                    >
                      {s("逐题辅导", "Coached")}
                    </button>
                    <button
                      type="button"
                      aria-pressed={selection.pace === "mock"}
                      onClick={() => onChange({ ...selection, pace: "mock" })}
                    >
                      {s("模拟面试", "Mock interview")}
                    </button>
                  </div>
                  <p className="fineprint" role="status">
                    {selection.pace === "mock"
                      ? s(
                          "先连续问答，复盘或结束时再反馈。",
                          "Feedback waits until review or finish.",
                        )
                      : s(
                          "每次回答后，获得简短反馈。",
                          "Receive brief feedback after each answer.",
                        )}
                  </p>
                </fieldset>
              )}
            {selected.category === "interview" &&
              prompt.id !== "roleplay-coach" && (
                <p className="fineprint">
                  {s(
                    "当前按所选教练辅导。连续模拟面试请使用情境扮演教练。",
                    "Use Role-play Coach for an uninterrupted mock interview.",
                  )}
                </p>
              )}
          </div>
        </details>
      )}
      {browsing && (
        <SceneBrowser
          available={available}
          promptId={prompt.id}
          returnFocus={trigger}
          selected={selected}
          locale={locale}
          onClose={() => setBrowsing(false)}
          onSelect={(scene) => {
            onChange(
              scene
                ? { sceneId: scene.id, background: "", pace: "coached" }
                : undefined,
            );
            setBrowsing(false);
          }}
        />
      )}
    </section>
  );
}
"}]

