[{"path":"src/SceneBrowser.tsx","content":"import { useEffect, useRef, useState, type RefObject } from "react";
import {
  sceneCategories,
  sceneGroups,
  type Scene,
  type SceneCategory,
} from "./scenes";
import { categoryEmoji, groupEmoji, sceneIcon } from "./scene-icons";
import type { Locale } from "./types";

export function SceneBrowser({
  available,
  promptId,
  returnFocus,
  selected,
  locale,
  onSelect,
  onClose,
}: {
  available: Scene[];
  promptId: string;
  returnFocus: RefObject<HTMLButtonElement | null>;
  selected?: Scene;
  locale: Locale;
  onSelect: (scene?: Scene) => void;
  onClose: () => void;
}) {
  const [category, setCategory] = useState<SceneCategory | undefined>(
    selected?.category,
  );
  const [group, setGroup] = useState<string | undefined>(selected?.group);
  const [query, setQuery] = useState("");
  const dialog = useRef<HTMLDialogElement>(null);
  const closeRef = useRef(onClose);
  closeRef.current = onClose;
  const token = useRef(`scene-${Date.now()}-${Math.random()}`);
  const heading = useRef<HTMLHeadingElement>(null);
  const s = (zh: string, en: string) => (locale === "en" ? en : zh);
  useEffect(() => {
    const element = dialog.current!;
    const previous = returnFocus.current;
    if (
      history.state?.talksproutSceneCoach === promptId &&
      typeof history.state?.talksproutSceneBrowser === "string"
    ) {
      token.current = history.state.talksproutSceneBrowser;
    } else {
      history.pushState(
        {
          ...history.state,
          talksproutSceneBrowser: token.current,
          talksproutSceneCoach: promptId,
        },
        "",
        location.href,
      );
    }
    const pop = () => {
      if (history.state?.talksproutSceneBrowser !== token.current)
        closeRef.current();
    };
    window.addEventListener("popstate", pop);
    element.showModal();
    heading.current?.focus({ preventScroll: true });
    return () => {
      window.removeEventListener("popstate", pop);
      element.close();
      if (history.state?.talksproutSceneBrowser === token.current)
        history.back();
      requestAnimationFrame(() => {
        if (previous?.isConnected) previous.focus({ preventScroll: true });
      });
    };
  }, []);
  const changePage = (nextCategory?: SceneCategory, nextGroup?: string) => {
    setCategory(nextCategory);
    setGroup(nextGroup);
    setQuery("");
    dialog.current?.querySelector(".scene-browser-scroll")?.scrollTo(0, 0);
    heading.current?.focus({ preventScroll: true });
  };
  const search = query.trim().toLowerCase();
  const scenes = available.filter((scene) =>
    search
      ? `${scene.title.zh} ${scene.title.en} ${sceneGroups.find((g) => g.id === scene.group)?.title.zh} ${sceneGroups.find((g) => g.id === scene.group)?.title.en} ${scene.goal}`
          .toLowerCase()
          .includes(search)
      : scene.group === group,
  );
  const title = group
    ? sceneGroups.find((g) => g.id === group)!.title[locale]
    : category
      ? sceneCategories.find((c) => c.id === category)!.title[locale]
      : s("选择场景", "Choose a scenario");
  return (
    <dialog
      ref={dialog}
      className="scene-browser"
      aria-labelledby="scene-browser-title"
      onKeyDown={(event) => {
        if (event.key !== "Tab") return;
        const controls = Array.from(
          event.currentTarget.querySelectorAll<HTMLElement>(
            'button:not(:disabled), input:not(:disabled), [tabindex="0"]',
          ),
        ).filter((element) => element.getClientRects().length > 0);
        if (!controls.length) return;
        // Explicit traversal also includes buttons when Safari's system setting
        // limits native Tab navigation to form fields.
        event.preventDefault();
        const current = controls.indexOf(document.activeElement as HTMLElement);
        const next =
          current < 0
            ? event.shiftKey
              ? controls.length - 1
              : 0
            : (current + (event.shiftKey ? -1 : 1) + controls.length) %
              controls.length;
        controls[next].focus();
      }}
      onCancel={(e) => {
        e.preventDefault();
        e.stopPropagation();
        onClose();
      }}
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <header className="scene-browser-toolbar">
        <button
          type="button"
          className="scene-back"
          aria-label={s("返回", "Back")}
          onClick={() =>
            group ? changePage(category) : category ? changePage() : onClose()
          }
        >
          <span aria-hidden="true">‹</span>
        </button>
        <h2 id="scene-browser-title" ref={heading} tabIndex={-1}>
          {title}
        </h2>
        <button type="button" className="scene-done" onClick={onClose}>
          {s("完成", "Done")}
        </button>
      </header>
      <div className="scene-browser-search">
        <span aria-hidden="true">⌕</span>
        <input
          id="scene-search"
          type="search"
          aria-label={s("搜索全部可用场景", "Search all available scenarios")}
          placeholder={s("搜索场景", "Search scenarios")}
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
      </div>
      <div className="scene-browser-scroll">
        <div className="scene-list">
          <button
            type="button"
            className="scene-row scene-none"
            aria-label={s("不指定场景", "No preset")}
            onClick={() => onSelect(undefined)}
          >
            <span className="scene-emoji" aria-hidden="true">
              💬
            </span>
            <span className="scene-row-copy">
              <strong>{s("不指定场景", "No preset")}</strong>
              <small>
                {s("自由选择聊天内容", "Let the conversation find its topic")}
              </small>
            </span>
            {!selected && (
              <span className="scene-check" aria-hidden="true">
                ✓
              </span>
            )}
          </button>
        </div>
        <p className="scene-section-label">
          {search
            ? s("搜索结果", "Search results")
            : group
              ? s("选择一个场景", "Choose a preset")
              : category
                ? s("按主题浏览", "Browse topics")
                : s("场景分类", "Categories")}
        </p>
        <div className="scene-list">
          {!search &&
            !category &&
            sceneCategories
              .filter((c) => available.some((scene) => scene.category === c.id))
              .map((c) => (
                <button
                  key={c.id}
                  type="button"
                  className="scene-row"
                  aria-label={c.title[locale]}
                  onClick={() => changePage(c.id)}
                >
                  <span className="scene-emoji" aria-hidden="true">
                    {categoryEmoji[c.id]}
                  </span>
                  <span className="scene-row-copy">
                    <strong>{c.title[locale]}</strong>
                    <small>
                      {
                        available.filter((scene) => scene.category === c.id)
                          .length
                      }
                      {s(" 个场景", " scenarios")}
                    </small>
                  </span>
                  <span className="scene-chevron" aria-hidden="true">
                    ›
                  </span>
                </button>
              ))}
          {!search &&
            category &&
            !group &&
            sceneGroups
              .filter(
                (g) =>
                  g.category === category &&
                  available.some((scene) => scene.group === g.id),
              )
              .map((g) => (
                <button
                  key={g.id}
                  type="button"
                  className="scene-row"
                  aria-label={g.title[locale]}
                  onClick={() => changePage(category, g.id)}
                >
                  <span className="scene-emoji" aria-hidden="true">
                    {groupEmoji[g.id]}
                  </span>
                  <span className="scene-row-copy">
                    <strong>{g.title[locale]}</strong>
                  </span>
                  <span className="scene-chevron" aria-hidden="true">
                    ›
                  </span>
                </button>
              ))}
          {(search || group) &&
            scenes.map((scene) => (
              <button
                key={scene.id}
                type="button"
                className="scene-row scene-option"
                aria-label={scene.title[locale]}
                aria-pressed={selected?.id === scene.id}
                onClick={() => onSelect(scene)}
              >
                <span className="scene-emoji" aria-hidden="true">
                  {sceneIcon(scene)}
                </span>
                <span className="scene-row-copy">
                  <strong>{scene.title[locale]}</strong>
                  {search && (
                    <small>
                      {
                        sceneCategories.find((c) => c.id === scene.category)!
                          .title[locale]
                      }
                    </small>
                  )}
                </span>
                {selected?.id === scene.id && (
                  <span className="scene-check" aria-hidden="true">
                    ✓
                  </span>
                )}
              </button>
            ))}
        </div>
        {search && !scenes.length && (
          <p className="scene-empty" role="status">
            {s(
              "没有找到场景，换个词试试",
              "No scenarios found. Try another word.",
            )}
          </p>
        )}
      </div>
    </dialog>
  );
}
"},{"path":"src/Settings.tsx","content":"import type { OfflineStatus } from "./offline-readiness";
import { Icon } from "./Icon";
import type { Locale } from "./types";
export function Settings({
  locale,
  onLocale,
  onInstall,
  onAbout,
  online,
  installed,
  offlineStatus,
}: {
  locale: Locale;
  onLocale: (locale: Locale) => void;
  onInstall: () => void;
  onAbout: () => void;
  online: boolean;
  installed: boolean;
  offlineStatus: OfflineStatus;
}) {
  const en = locale === "en",
    s = (zh: string, english: string) => (en ? english : zh);
  return (
    <section
      className="settings-view"
      aria-label={s("应用设置", "App settings")}
    >
      <h2 className="section-label">{s("偏好设置", "Preferences")}</h2>
      <div className="settings-group native-list">
        <fieldset className="language-setting">
          <legend>{s("界面语言", "Interface language")}</legend>
          <div className="language-options">
            {(
              [
                ["zh", "中文"],
                ["en", "English"],
              ] as const
            ).map(([value, label]) => (
              <label key={value}>
                <input
                  type="radio"
                  name="language"
                  value={value}
                  checked={locale === value}
                  onChange={() => onLocale(value)}
                />
                <span>{label}</span>
              </label>
            ))}
          </div>
          <p>{s("复习与学习辅助提示词的解释语言会跟随界面语言，英语练习内容保持英文。", "Review and learning helper explanations follow your interface language; English practice content stays in English.")}</p>
        </fieldset>
      </div>
      <h2 className="section-label">
        {s("使用 TalkSprout", "Using TalkSprout")}
      </h2>
      <div className="settings-group native-list">
        <button
          id="install"
          className="settings-row"
          onClick={(event) => {
            event.currentTarget.focus({ preventScroll: true });
            onInstall();
          }}
        >
          <span className="entry-icon">
            <Icon name="download" />
          </span>
          <span className="row-text">
            <strong>
              {installed
                ? s("已添加到主屏幕", "Added to Home Screen")
                : s("安装到手机", "Install app")}
            </strong>
            <small>
              {s(
                "像 App 一样，随时打开",
                "Open it like an app, whenever you need",
              )}
            </small>
          </span>
          <Icon name="chevron" />
        </button>
        <button
          id="about"
          className="settings-row"
          onClick={(event) => {
            event.currentTarget.focus({ preventScroll: true });
            onAbout();
          }}
        >
          <span className="entry-icon">
            <Icon name="help" />
          </span>
          <span className="row-text">
            <strong>{s("使用说明", "Instructions")}</strong>
            <small>
              {s(
                "开场练习、语音提示与结束复习",
                "Starting practice, spoken prompts, and reviews",
              )}
            </small>
          </span>
          <Icon name="chevron" />
        </button>
      </div>
      <h2 className="section-label">{s("本机与离线", "On this device")}</h2>
      <div className="settings-group settings-notes">
        <div>
          <strong>
            {online
              ? s("当前在线", "Currently online")
              : s("当前离线", "Currently offline")}
          </strong>
          <p>
            {offlineStatus === "ready"
              ? s("离线内容已就绪，提示词可离线浏览和复制。外部 AI 仍需网络。", "Offline content is ready. Browse and copy prompts offline; your external AI still needs a connection.")
              : offlineStatus === "installing"
                ? s("正在准备离线内容，请保持页面打开并联网。", "Preparing offline content. Keep this page open and connected.")
                : offlineStatus === "unavailable"
                  ? s("此浏览器当前无法保存离线内容，请联网使用。", "This browser cannot currently save offline content. Use the app online.")
                  : s("尚未确认离线内容已就绪，请联网打开并等待准备完成。", "Offline readiness is not confirmed yet. Open the app online and allow preparation to finish.")}
          </p>
        </div>
        <div>
          <strong>
            {s("收藏只保存在本机", "Favorites stay on this device")}
          </strong>
          <p>
            {s(
              "无需账号，无分析追踪。本站不接收或保存 AI 聊天；清除浏览器数据会移除收藏和偏好。",
              "No account or analytics. This app does not receive or save AI chats. Clearing browser data removes favorites and preferences.",
            )}
          </p>
        </div>
      </div>
      <p className="settings-signature">TalkSprout · OctopusGarage</p>
    </section>
  );
}
"},{"path":"src/guides.css","content":".guide-hub, .guide-reader { max-width: 760px; margin-inline: auto; }
.guide-hub[hidden] { display: none; }
.guide-search { width: 100%; margin-bottom: 8px; }
.guide-group { margin-block: 24px 30px; }
.guide-group > h2 { font-size: 16px; line-height: 1.5; margin: 0 0 12px; }
.guide-results { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 48px; color: var(--muted); font-size: 13px; }
.guide-results p { margin: 0; }
.guide-results button, .guide-back { min-height: 44px; border: 0; background: transparent; color: var(--green); cursor: pointer; }
.guide-results button { padding-inline: 8px; }
.guide-entry { display: flex; align-items: center; gap: 16px; width: 100%; min-height: 96px; padding: 20px; border: 0; background: transparent; color: var(--ink); text-align: left; cursor: pointer; }
.guide-entry + .guide-entry { border-top: 1px solid var(--border); }
.guide-entry > svg { flex-shrink: 0; width: 18px; color: var(--muted); }
.guide-entry-text { display: flex; flex: 1; min-width: 0; flex-direction: column; gap: 6px; }
.guide-entry-text strong { font-size: 16px; line-height: 1.5; }
.guide-entry-text > span { color: var(--muted); font-size: 13px; line-height: 1.7; }
.guide-back { display: inline-flex; align-items: center; gap: 5px; padding: 0 8px 0 0; margin-bottom: 18px; }
.guide-back svg { width: 18px; }
.guide-reader { font-size: 16px; line-height: 1.9; overflow-wrap: anywhere; padding-bottom: 24px; }
.guide-summary { font-size: 19px; line-height: 1.75; margin: 0 0 24px; }
.guide-reader h2 { font-size: 20px; line-height: 1.6; margin: 0 0 14px; }
.guide-section { margin-block: 28px; }
.guide-reader p { margin-block: 12px; }
.guide-reader ol { padding-left: 1.6em; }
.guide-reader li { padding-left: 4px; margin-bottom: 12px; }
.guide-example { margin-top: 20px; padding: 18px 20px; border: 1px solid var(--border); border-radius: 14px; background: var(--surface); }
.guide-example strong { font-size: 13px; color: var(--green); }
.guide-example p { white-space: pre-line; }
.guide-reading .app-header h1 { font-size: 22px; line-height: 1.4; }
@media (hover: hover) { .guide-entry:hover { background: #f1f5ef; } }
@media (max-width: 760px) {
  .guide-entry { padding: 17px 16px; gap: 12px; }
  .guide-reader { font-size: 15px; }
  .guide-reader h2 { font-size: 18px; }
  .guide-summary { font-size: 17px; }
  .guide-reading .app-header .connection { display: none; }
  .guide-reading .app-header h1 { font-size: 20px; }
}

.guide-shelves { display: flex; gap: 4px; padding: 4px; margin: 0 0 20px; border-radius: 14px; background: var(--tint); }
.guide-shelves button { flex: 1; min-height: 44px; padding: 10px 12px; border: 0; border-radius: 10px; background: transparent; color: var(--muted); font-weight: 600; cursor: pointer; }
.guide-shelves button[aria-pressed="true"] { background: var(--surface); color: var(--green); box-shadow: 0 1px 4px #223e3410; }
.guide-topics { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }
.guide-topics button { min-height: 44px; padding: 8px 14px; border-radius: 12px; border: 1px solid var(--border); background: var(--surface); color: var(--ink); cursor: pointer; }
.guide-topics button[aria-pressed="true"] { background: var(--green); border-color: var(--green); color: #fff; }
.guide-practice { margin-top: 32px; }
.guide-practice > p { color: var(--muted); font-size: 14px; }
.guide-practice > div { display: flex; flex-direction: column; gap: 10px; }
