export function useAppFrame(view: string) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const positions = useRef(new Map<string, number>());
  const activeView = useRef(view);
  const [keyboardOpen, setKeyboardOpen] = useState(false);

  useLayoutEffect(() => {
    activeView.current = view;
    if (scrollRef.current)
      scrollRef.current.scrollTop = positions.current.get(view) ?? 0;
  }, [view]);

  useEffect(() => {
    const viewport = window.visualViewport;
    if (!viewport) return;
    let frame = 0;
    const update = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => {
        const zoomed = Math.abs(viewport.scale - 1) > 0.05;
        const unzoomedHeight = viewport.height * viewport.scale;
        const mobile =
          innerWidth <= 760 || matchMedia("(pointer: coarse)").matches;
        const field = document.activeElement;
        const editing =
          (field instanceof HTMLInputElement &&
            !field.readOnly &&
            ![
              "checkbox",
              "radio",
              "button",
              "file",
              "range",
              "color",
              "submit",
              "reset",
            ].includes(field.type)) ||
          (field instanceof HTMLTextAreaElement && !field.readOnly);
        const keyboard =
          mobile && editing && innerHeight - unzoomedHeight > 120;
        setKeyboardOpen(keyboard);
        let height = innerHeight;
        if (mobile && !zoomed) height = viewport.height;
        else if (mobile && keyboard)
          height = Math.min(innerHeight, unzoomedHeight);
        document.documentElement.style.setProperty(
          "--app-height",
          `${height}px`,
        );
        document.documentElement.style.setProperty(
          "--app-top",
          `${keyboard && !zoomed ? viewport.offsetTop : 0}px`,
        );
        if (keyboard && field instanceof HTMLElement)
          field.scrollIntoView({ block: "nearest" });
      });
    };
    update();
    for (const event of ["resize", "scroll"])
      viewport.addEventListener(event, update);
    window.addEventListener("resize", update);
    document.addEventListener("focusin", update);
    document.addEventListener("focusout", update);
    return () => {
      cancelAnimationFrame(frame);
      for (const event of ["resize", "scroll"])
        viewport.removeEventListener(event, update);
      window.removeEventListener("resize", update);
      document.removeEventListener("focusin", update);
      document.removeEventListener("focusout", update);
      document.documentElement.style.removeProperty("--app-height");
      document.documentElement.style.removeProperty("--app-top");
    };
  }, []);

  return {
    scrollRef,
    keyboardOpen,
    onScroll: () => {
      if (scrollRef.current)
        positions.current.set(activeView.current, scrollRef.current.scrollTop);
    },
  };
}
"}]

[{"path":"src/useRightEdgeBack.ts","content":"import { useEffect, useRef } from "react";

interface Swipe {
  id: number;
  x: number;
  y: number;
  horizontal: boolean;
}

/** App-level gesture; native system navigation may cancel the touch sequence. */
export function useRightEdgeBack(onBack: (() => void) | null, view: string) {
  const callback = useRef(onBack);
  callback.current = onBack;
  const suppressClickUntil = useRef(0);
  useEffect(() => {
    let swipe: Swipe | null = null;
    const reset = () => {
      swipe = null;
    };
    const start = (event: TouchEvent) => {
      reset();
      if (!callback.current || event.touches.length !== 1) return;
      const touch = event.touches[0];
      const target = event.target;
      if (
        touch.clientX < innerWidth - 32 ||
        touch.clientX > innerWidth ||
        Math.abs((window.visualViewport?.scale ?? 1) - 1) > 0.05 ||
        (window.getSelection()?.toString().length ?? 0) > 0 ||
        (target instanceof Element &&
          target.closest(
            'input, textarea, select, [contenteditable]:not([contenteditable="false"]), [role="slider"]',
          ))
      )
        return;
      swipe = {
        id: touch.identifier,
        x: touch.clientX,
        y: touch.clientY,
        horizontal: false,
      };
    };
    const move = (event: TouchEvent) => {
      if (!swipe) return;
      if (event.touches.length !== 1) return reset();
      const touch = event.touches[0];
      if (touch.identifier !== swipe.id) return reset();
      const dx = swipe.x - touch.clientX;
      const dy = Math.abs(touch.clientY - swipe.y);
      if (!swipe.horizontal) {
        if (Math.max(Math.abs(dx), dy) < 12) return;
        if (dx <= dy * 1.5) return reset();
        swipe.horizontal = true;
      }
      // Once horizontal intent is established, keep scrolling from taking over.
      if (event.cancelable) event.preventDefault();
      else reset();
    };
    const end = (event: TouchEvent) => {
      const current = swipe;
      reset();
      if (!current || !current.horizontal || event.touches.length) return;
      const touch = Array.from(event.changedTouches).find(
        (t) => t.identifier === current.id,
      );
      if (!touch || (window.getSelection()?.toString().length ?? 0) > 0) return;
      const dx = current.x - touch.clientX;
      if (dx < 72 || dx < Math.abs(touch.clientY - current.y) * 1.5) return;
      if (event.cancelable) event.preventDefault();
      suppressClickUntil.current = Date.now() + 400;
      callback.current?.();
    };
    const click = (event: MouseEvent) => {
      if (Date.now() < suppressClickUntil.current && event.detail !== 0) {
        event.preventDefault();
        event.stopImmediatePropagation();
      }
    };
    document.addEventListener("touchstart", start, { passive: true, capture: true });
    document.addEventListener("touchmove", move, { passive: false, capture: true });
    document.addEventListener("touchend", end, { passive: false, capture: true });
    document.addEventListener("touchcancel", reset, true);
    document.addEventListener("click", click, true);
    window.addEventListener("blur", reset);
    return () => {
      document.removeEventListener("touchstart", start, true);
      document.removeEventListener("touchmove", move, true);
      document.removeEventListener("touchend", end, true);
      document.removeEventListener("touchcancel", reset, true);
      document.removeEventListener("click", click, true);
      window.removeEventListener("blur", reset);
    };
  }, [view]);
}
"}]

