[{"path":"src/QuickAccess.tsx","content":"import { useEffect, useId, useLayoutEffect, useRef, useState } from "react";
import { focusPracticeCollection } from "./home-focus";
import { allPrompts } from "./prompts";
import { learningPrompts } from "./content/learning";
import { scenes } from "./scenes";
import { practiceHref, recentHref, shortcutKey, type PracticeShortcut, type RecentPrompt } from "./shortcuts";
import { navigate } from "./navigation";
import { Icon } from "./Icon";
import type { Locale } from "./types";

function open(href: string, id: string, learning = false) {
  navigate(href, learning ? { talksproutLearningPrompt: id } : { talksproutPrompt: id });
}
export function shortcutLabel(entry: PracticeShortcut, locale: Locale) {
  const prompt = allPrompts.find(p => p.id === entry.promptId)!;
  const scene = scenes.find(s => s.id === entry.sceneId);
  return [locale === "en" ? prompt.english : prompt.title, scene?.title[locale]].filter(Boolean).join(" · ");
}
export function SavedPracticeList({ items, locale, onRemove }: { items: PracticeShortcut[]; locale: Locale; onRemove: (item: PracticeShortcut) => void }) {
  const [expanded, setExpanded] = useState(false);
  const listId = useId();
  const canExpand = items.length > 3;
  const list = useRef<HTMLDivElement>(null);
  const previousFocus = useRef<{ element: HTMLElement; index: number } | null>(null);
  useLayoutEffect(() => {
    const previous = previousFocus.current;
    if (!previous || previous.element.isConnected) return;
    previousFocus.current = null;
    // Restore only removed focus; a new connected target belongs to the user.
    if (document.activeElement !== document.body) return;
    const rows = list.current?.querySelectorAll<HTMLElement>(".quick-open");
    const target = rows?.[Math.min(previous.index, rows.length - 1)];
    if (target) target.focus({ preventScroll: true });
    else focusPracticeCollection();
  }, [items, expanded]);
  useEffect(() => {
    if (!canExpand) setExpanded(false);
  }, [canExpand]);
  if (!items.length) return null;
  const en = locale === "en";
  const visibleItems = expanded ? items : items.slice(0, 3);
  return <section className="quick-access" aria-label={en ? "Saved practice combinations" : "常用练习组合"}
    onFocusCapture={(event) => {
      const element = event.target as HTMLElement;
      const row = element.closest(".quick-row");
      const rows = Array.from(list.current?.children ?? []);
      previousFocus.current = { element, index: row ? rows.indexOf(row) : rows.length - 1 };
    }}>
    <h2 className="section-label">{en ? "Saved combinations" : "常用组合"}</h2>
    <div className="native-list" id={listId} ref={list}>{visibleItems.map(item => <div className="quick-row" key={shortcutKey(item)}>
      <button className="quick-open" onClick={() => open(practiceHref(item), item.promptId)}>
        <strong>{shortcutLabel(item, locale)}</strong>
        <small>{item.variant === "spoken" ? (en ? "Spoken opening" : "语音开场白") : (en ? "Full prompt" : "完整提示词")}{item.pace === "mock" ? (en ? " · Mock interview" : " · 模拟面试") : ""}</small>
      </button>
      <button className="icon-button" aria-label={`${en ? "Remove combination" : "移除组合"}：${shortcutLabel(item, locale)}`} onClick={() => onRemove(item)}><Icon name="close" /></button>
    </div>)}</div>
    {canExpand && <button className="quick-access-toggle" aria-expanded={expanded} aria-controls={listId} onClick={() => setExpanded(value => !value)}>
      {expanded ? (en ? "Show fewer combinations" : "收起组合") : (en ? `Show all ${items.length} combinations` : `展开全部 ${items.length} 个组合`)}
    </button>}
  </section>;
}
export function RecentList({ items, locale }: { items: RecentPrompt[]; locale: Locale }) {
  if (!items.length) return null;
  const en = locale === "en";
  return <section className="quick-access" aria-label={en ? "Recently copied" : "最近复制"}>
    <h2 className="section-label">{en ? "Recently copied" : "最近复制"}</h2>
    <div className="native-list">{items.slice(0, 3).map(item => {
      const prompt = allPrompts.find(p => p.id === item.promptId);
      const learning = learningPrompts.find(p => p.id === item.promptId);
      const title = item.kind === "practice" ? shortcutLabel(item, locale) : item.kind === "learning" ? learning!.title[locale] : en ? prompt!.english : prompt!.title;
      return <button className="quick-open" key={recentHref(item)} onClick={() => open(recentHref(item), item.promptId, item.kind === "learning")}>
        <strong>{title}</strong>
        {item.kind !== "learning" && <small>{item.variant === "spoken" ? (en ? "Spoken version" : "简短语音版") : (en ? "Full prompt" : "完整提示词")}{item.kind === "practice" && item.pace === "mock" ? (en ? " · Mock interview" : " · 模拟面试") : ""}{item.kind === "review" && item.source === "transcript" ? (en ? " · Another transcript" : " · 其他聊天记录") : ""}</small>}
      </button>;
    })}</div>
  </section>;
}
"},{"path":"src/clipboard-writer.ts","content":"export interface ClipboardRequest {
  text: string;
  onDelivered?: () => void | Promise<void>;
  onSuccess?: () => void;
  onFailure?: () => void;
}

/** One app-wide writer; feedback callbacks belong to the initiating view only. */
export function createClipboardWriter(
  writeText: (text: string) => Promise<void>,
  getContext: () => string,
  onBusyChange: (busy: boolean) => void = () => {},
) {
  let busy = false;
  let generation = 0;
  return {
    invalidate() { generation++; },
    async write(request: ClipboardRequest): Promise<boolean> {
      if (busy) return false;
      busy = true;
      const token = ++generation;
      const context = getContext();
      const current = () => token === generation && context === getContext();
      onBusyChange(true);
      try {
        try {
          // Invoke during the original click gesture, before any await.
          await writeText(request.text);
        } catch {
          if (current()) request.onFailure?.();
          return false;
        }
        await request.onDelivered?.();
        if (current()) request.onSuccess?.();
        return true;
      } finally {
        busy = false;
        onBusyChange(false);
      }
    },
  };
}
export type ClipboardWriter = ReturnType<typeof createClipboardWriter>;
"},{"path":"src/saved-snapshot.ts","content":"/** Native transactions serialize saved metadata across same-origin windows. */
export function createSavedSnapshot(factory: IDBFactory | undefined) {
  let connection: Promise<IDBDatabase> | undefined;
  function open(): Promise<IDBDatabase> {
    if (!factory) return Promise.reject(new Error('IndexedDB is unavailable'));
    if (connection) return connection;
    const attempt = new Promise<IDBDatabase>((resolve, reject) => {
      const request = factory.open('talksprout:saved', 1);
      let blocked = false;
      request.onupgradeneeded = () => {
        if (!request.result.objectStoreNames.contains('snapshot')) {
          request.result.createObjectStore('snapshot');
        }
      };
      request.onerror = () => reject(request.error ?? new Error('Could not open saved metadata'));
      request.onblocked = () => {
        blocked = true;
        reject(new Error('Saved metadata database upgrade is blocked'));
      };
      request.onsuccess = () => {
        const database = request.result;
        if (blocked) { database.close(); return; }
        database.onversionchange = () => {
          database.close();
          connection = undefined;
        };
        resolve(database);
      };
    });
    connection = attempt;
    void attempt.catch(() => { if (connection === attempt) connection = undefined; });
    return attempt;
  }
  async function transact<T>(
    mode: IDBTransactionMode,
    change: (raw: unknown | undefined) => T,
    beforeCommit?: (next: T) => void,
  ): Promise<T> {
    const database = await open();
    return new Promise<T>((resolve, reject) => {
      const transaction = database.transaction('snapshot', mode);
      const store = transaction.objectStore('snapshot');
      let next: T;
      let failure: unknown;
      transaction.oncomplete = () => resolve(next);
      transaction.onabort = () => reject(failure ?? transaction.error ?? new Error('Saved metadata transaction aborted'));
      transaction.onerror = () => {
        failure ??= transaction.error ?? new Error('Saved metadata transaction failed');
      };
      const request = store.get('current');
      request.onsuccess = () => {
        try {
          next = change(request.result as unknown);
          beforeCommit?.(next);
          if (mode === 'readwrite') store.put(next, 'current');
        } catch (error) {
          failure = error;
          transaction.abort();
        }
      };
    });
  }
  return {
    read: (): Promise<unknown | undefined> => transact('readonly', raw => raw),
    update: <T>(change: (raw: unknown | undefined) => T, beforeCommit: (next: T) => void): Promise<T> =>
      transact('readwrite', change, beforeCommit),
  };
}
"},{"path":"src/shortcuts.ts","content":"import { allPrompts } from "./prompts";
import { learningPrompts } from "./content/learning";
import { compatibleScenes } from "./scenes";
import type { PromptVariant, ReviewSource } from "./types";

export interface PracticeShortcut {
  promptId: string;
  variant: PromptVariant;
  sceneId?: string;
  pace: "coached" | "mock";
}
export type RecentPrompt =
  | ({ kind: "practice" } & PracticeShortcut)
  | { kind: "review"; promptId: string; variant: PromptVariant; source: ReviewSource }
  | { kind: "learning"; promptId: string };
type ReadStorage = Pick<Storage, "getItem"> | null;
function object(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
function variant(value: unknown): value is PromptVariant {
  return value === "full" || value === "spoken";
}
function practice(value: unknown): PracticeShortcut | null {
  if (!object(value) || !variant(value.variant) || (value.pace !== "coached" && value.pace !== "mock")) return null;
  const prompt = allPrompts.find(p => p.id === value.promptId && p.kind !== "review");
  if (!prompt) return null;
  const scene = value.sceneId === undefined ? undefined : compatibleScenes(prompt).find(s => s.id === value.sceneId);
  if ((value.sceneId !== undefined && !scene) || (value.pace === "mock" && (prompt.id !== "roleplay-coach" || scene?.category !== "interview"))) return null;
  return { promptId: prompt.id, variant: value.variant, ...(scene ? { sceneId: scene.id } : {}), pace: value.pace };
}
function recent(value: unknown): RecentPrompt | null {
  if (!object(value)) return null;
  if (value.kind === "practice") {
    const entry = practice(value);
    return entry ? { kind: "practice", ...entry } : null;
  }
  if (value.kind === "learning" && learningPrompts.some(p => p.id === value.promptId)) return { kind: "learning", promptId: value.promptId as string };
  if (value.kind === "review" && allPrompts.some(p => p.id === value.promptId && p.kind === "review") && variant(value.variant) && (value.source === "current" || value.source === "transcript")) return { kind: "review", promptId: value.promptId as string, variant: value.variant, source: value.source };
  return null;
}
function read(storage: ReadStorage, key: string): string | null {
  try { return storage?.getItem(key) ?? null; } catch { return null; }
}
function array(raw: string | null): unknown[] {
  try { const value: unknown = JSON.parse(raw ?? "null"); return Array.isArray(value) ? value : []; } catch { return []; }
}
export function shortcutKey(shortcut: PracticeShortcut): string {
  return JSON.stringify([shortcut.promptId, shortcut.variant, shortcut.sceneId ?? null, shortcut.pace]);
}
export function practiceHref(shortcut: PracticeShortcut): string {
  const query = new URLSearchParams({ prompt: shortcut.promptId });
  if (shortcut.sceneId) query.set("scene", shortcut.sceneId);
  if (shortcut.pace === "mock") query.set("pace", "mock");
  if (shortcut.variant === "spoken") query.set("format", "spoken");
  return `#library?${query}`;
}
export function recentHref(entry: RecentPrompt): string {
  if (entry.kind === "practice") return practiceHref(entry);
  const query = new URLSearchParams({ prompt: entry.promptId });
  if (entry.kind === "review") {
    if (entry.source === "transcript") query.set("source", "transcript");
    if (entry.variant === "spoken") query.set("format", "spoken");
  }
  return `#${entry.kind}?${query}`;
}
export function readPracticeShortcuts(storage: ReadStorage): PracticeShortcut[] {
  const seen = new Set<string>();
  return array(read(storage, "talksprout:practice-shortcuts")).flatMap(value => {
    const entry = practice(value);
    if (!entry || seen.has(shortcutKey(entry))) return [];
    seen.add(shortcutKey(entry));
    return [entry];
  });
}
function recentKey(entry: RecentPrompt): string {
  return entry.kind === "practice" ? `practice:${shortcutKey(entry)}` : entry.kind === "review" ? JSON.stringify([entry.kind, entry.promptId, entry.variant, entry.source]) : `learning:${entry.promptId}`;
}
function bounded(values: unknown[]): RecentPrompt[] {
  const seen = new Set<string>();
  const counts = { practice: 0, review: 0, learning: 0 };
  return values.flatMap(value => {
    const entry = recent(value);
    if (!entry || seen.has(recentKey(entry)) || counts[entry.kind] >= 4) return [];
    seen.add(recentKey(entry)); counts[entry.kind]++;
    return [entry];
  });
}
export function recordRecent(items: RecentPrompt[], entry: RecentPrompt): RecentPrompt[] {
  return bounded([entry, ...items]);
}
export function readRecentPrompts(storage: ReadStorage): RecentPrompt[] {
  const raw = read(storage, "talksprout:recent-items");
  if (raw !== null) return bounded(array(raw));
  return bounded(array(read(storage, "talksprout:recent")).map(id => {
    const prompt = allPrompts.find(p => p.id === id);
    return prompt?.kind === "review" ? { kind: "review", promptId: prompt.id, variant: "full", source: "current" } : prompt ? { kind: "practice", promptId: prompt.id, variant: "full", pace: "coached" } : null;
  }));
}
"},{"path":"src/usePromptClipboard.ts","content":"import { useEffect, useRef, useState } from "react";
import { createClipboardWriter, type ClipboardWriter } from "./clipboard-writer";

export function usePromptClipboard() {
  const [copying, setCopying] = useState(false);
  const mounted = useRef(true);
  const writer = useRef<ClipboardWriter | null>(null);
  if (!writer.current) writer.current = createClipboardWriter(
    (text) => navigator.clipboard.writeText(text),
    () => location.href,
    (busy) => { if (mounted.current) setCopying(busy); },
  );
  useEffect(() => {
    mounted.current = true;
    return () => { mounted.current = false; writer.current?.invalidate(); };
  }, []);
  return { copying, writer: writer.current };
}
"},{"path":"src/useSavedPrompts.ts","content":"import { useEffect, useRef, useState } from "react";
import { createSavedSnapshot } from "./saved-snapshot";
import { readSaved } from "./library";
import { allPrompts } from "./prompts";
import { learningPrompts } from "./content/learning";
import { readPracticeShortcuts, readRecentPrompts, recordRecent, shortcutKey, type PracticeShortcut, type RecentPrompt } from "./shortcuts";

const signalKey = "talksprout:saved-updated";
const keys = {
  favorites: "talksprout:favorites",
  shortcuts: "talksprout:practice-shortcuts",
  learningFavorites: "talksprout:learning-favorites",
  recent: "talksprout:recent-items",
  legacyRecent: "talksprout:recent",
};
interface SavedState {
  favorites: string[];
  shortcuts: PracticeShortcut[];
  learningFavorites: string[];
  recent: RecentPrompt[];
}
function read(storage: Pick<Storage, "getItem"> | null): SavedState {
  return {
    favorites: readSaved(storage, keys.favorites).filter(id => allPrompts.some(p => p.id === id)),
    shortcuts: readPracticeShortcuts(storage),
    learningFavorites: readSaved(storage, keys.learningFavorites).filter(id => learningPrompts.some(p => p.id === id)),
    recent: readRecentPrompts(storage),
  };
}
let snapshot: ReturnType<typeof createSavedSnapshot> | undefined;
try { if (globalThis.indexedDB) snapshot = createSavedSnapshot(globalThis.indexedDB); } catch {}
function decode(raw: unknown): SavedState {
  const value = raw && typeof raw === "object" ? raw as Record<string, unknown> : {};
  const fields: Record<string, unknown> = {
    [keys.favorites]: value.favorites,
    [keys.shortcuts]: value.shortcuts,
    [keys.learningFavorites]: value.learningFavorites,
    [keys.recent]: value.recent,
  };
  return read({ getItem: key => fields[key] === undefined ? null : JSON.stringify(fields[key]) });
}
function membership<T>(items: T[], item: T, selected: boolean, equal: (value: T) => boolean): T[] {
  return selected ? items.some(equal) ? items : [...items, item] : items.filter(value => !equal(value));
}

export function useSavedPrompts(storage: Storage | null) {
  const [state, setState] = useState(() => read(storage));
  // Store requested per-item operations, never an old full-array snapshot.
  const pending = useRef<{ key: keyof SavedState; apply: (state: SavedState) => SavedState }[]>([]);
  const reconcile = (latest: SavedState) => pending.current.reduce((next, intent) => intent.apply(next), latest);
  const current = useRef(state);
  current.current = state;
  const version = useRef(0);
  const mounted = useRef(true);
  const channel = useRef<BroadcastChannel | null>(null);
  const refreshSaved = useRef<() => void>(() => {});
  const publish = (next: SavedState) => {
    version.current++;
    current.current = next;
    if (mounted.current) setState(next);
  };
  useEffect(() => {
    mounted.current = true;
    const refresh = async () => {
      const request = ++version.current;
      let latest = read(storage);
      if (snapshot) {
        try {
          const raw = await snapshot.read();
          if (raw !== undefined) latest = decode(raw);
        } catch { /* Keep validated legacy/session data when native storage is unavailable. */ }
      }
      if (mounted.current && request === version.current) publish(reconcile(latest));
    };
    refreshSaved.current = () => { void refresh(); };
    try {
      channel.current = new BroadcastChannel("talksprout:saved");
      channel.current.onmessage = () => { void refresh(); };
    } catch { channel.current = null; }
    const foreground = () => { if (document.visibilityState === "visible") void refresh(); };
    const sync = (event: StorageEvent) => {
      if ((event.storageArea && event.storageArea !== storage) || (event.key !== null && event.key !== signalKey && !Object.values(keys).includes(event.key))) return;
      if (event.key === null) {
        pending.current = [];
        version.current++;
        if (snapshot) {
          void snapshot.update(() => read(storage), () => {}).then(() => refresh(), () => refresh());
          return;
        }
      }
      void refresh();
    };
    window.addEventListener("storage", sync);
    window.addEventListener("focus", foreground);
    document.addEventListener("visibilitychange", foreground);
    void refresh();
    return () => {
      mounted.current = false;
      version.current++;
      refreshSaved.current = () => {};
      channel.current?.close();
      channel.current = null;
      window.removeEventListener("storage", sync);
      window.removeEventListener("focus", foreground);
      document.removeEventListener("visibilitychange", foreground);
    };
  }, [storage]);
  const mutate = async <K extends keyof SavedState>(key: K, storageKey: string, update: (latest: SavedState[K]) => SavedState[K]): Promise<boolean> => {
    const intent = { key, apply: (latest: SavedState): SavedState => ({ ...latest, [key]: update(latest[key]) }) };
    if (snapshot) {
      let attempted: SavedState | undefined;
      try {
        const next = await snapshot.update(raw => {
          attempted = intent.apply(reconcile(raw === undefined ? read(storage) : decode(raw)));
          return attempted;
        }, next => {
          if (!storage) throw new Error("Local preferences unavailable");
          // Compatibility mirrors are not the transaction's source of truth.
          for (const field of ["favorites", "shortcuts", "learningFavorites", "recent"] as const)
            storage.setItem(keys[field], JSON.stringify(next[field]));
        });
        pending.current = [];
        publish(next);
        // Mirrors may already contain these bytes after an aborted attempt.
        // Notify only after native commit, even when no storage event is emitted.
        try {
          if (channel.current) channel.current.postMessage("changed");
          else storage?.setItem(signalKey, `${Date.now()}-${Math.random()}`);
        } catch { /* Foreground refresh still reconciles committed data. */ }
        refreshSaved.current();
        return true;
      } catch {
        pending.current.push(intent);
        publish(attempted ?? intent.apply(current.current));
        return false;
      }
    }
    let entered = false;
    const write = () => {
      entered = true;
      let latest = current.current;
      try {
        if (storage) { storage.getItem(storageKey); latest = read(storage); }
      } catch { /* Keep this window usable when storage access is blocked. */ }
      const next = intent.apply(reconcile(latest));
      publish(next);
      try {
        if (!storage) { pending.current.push(intent); return false; }
        storage.setItem(storageKey, JSON.stringify(next[key]));
        pending.current = pending.current.filter(item => item.key !== key);
        return true;
      } catch { pending.current.push(intent); return false; }
    };
    // Legacy-only fallback; native transactions above provide cross-window atomicity.
    if (navigator.locks) {
      try { return await navigator.locks.request("talksprout:saved-state", write); }
      catch { return entered ? false : write(); }
    }
    return write();
  };
  return {
    ...state,
    toggleFavorite(id: string) {
      if (!allPrompts.some(p => p.id === id)) return Promise.resolve(false);
      const selected = !current.current.favorites.includes(id);
      return mutate("favorites", keys.favorites, latest => membership(latest, id, selected, item => item === id));
    },
    toggleShortcut(entry: PracticeShortcut) {
      const key = shortcutKey(entry);
      const selected = !current.current.shortcuts.some(item => shortcutKey(item) === key);
      return mutate("shortcuts", keys.shortcuts, latest => membership(latest, entry, selected, item => shortcutKey(item) === key));
    },
    toggleLearningFavorite(id: string) {
      if (!learningPrompts.some(p => p.id === id)) return Promise.resolve(false);
      const selected = !current.current.learningFavorites.includes(id);
      return mutate("learningFavorites", keys.learningFavorites, latest => membership(latest, id, selected, item => item === id));
    },
    record(entry: RecentPrompt) {
      return mutate("recent", keys.recent, latest => recordRecent(latest, entry));
    },
  };
}
"}]

[{"path":"tests/app-update.test.ts","content":"import { test, mock } from "node:test";
import assert from "node:assert/strict";
import {
  createAppUpdateManager,
  type AppUpdateSnapshot,
} from "../src/app-update";

function harness(initiallyControlled = true) {
  class Worker extends EventTarget {
    state: ServiceWorkerState = "installed";
    messages = 0;
    throws = false;
    postMessage() {
      this.messages++;
      if (this.throws) throw Error("Worker is gone");
    }
  }
  const old = new Worker();
  old.state = "activated";
  const next = new Worker();
  const registration = Object.assign(new EventTarget(), {
    waiting: next as Worker | null,
    installing: null as Worker | null,
    active: old as Worker | null,
    updates: 0,
    update: async () => {
      registration.updates++;
      return registration;
    },
  });
  const container = Object.assign(new EventTarget(), {
    controller: initiallyControlled ? old : (null as Worker | null),
    register: async () => registration,
  });
  let snapshot: AppUpdateSnapshot = { phase: "idle" };
  let reloads = 0;
  const manager = createAppUpdateManager({
    container: container as unknown as ServiceWorkerContainer,
    onChange: (s) => (snapshot = s),
    reload: () => reloads++,
    onRegistrationError: () => {},
  });
  return {
    old,
    next,
    registration,
    container,
    manager,
    get snapshot() {
      return snapshot;
    },
    get reloads() {
      return reloads;
    },
    activate(events = true) {
      next.state = "activated";
      registration.active = next;
      registration.waiting = null;
      if (events) next.dispatchEvent(new Event("statechange"));
    },
  };
}

test("acceptance gives immediate feedback and blocks duplicate requests", async () => {
  const h = harness();
  await h.manager.start("sw.js");
  assert.equal(h.snapshot.phase, "available");
  h.manager.request();
  h.manager.request();
  assert.equal(h.snapshot.phase, "applying");
  assert.equal(h.next.messages, 1);
  h.manager.dispose();
});
test("activation without controllerchange or statechange still reloads exactly once", async () => {
  mock.timers.enable({ apis: ["setTimeout", "setInterval"] });
  const h = harness();
  await h.manager.start("sw.js");
  h.manager.request();
  h.activate(false);
  mock.timers.tick(500);
  assert.equal(h.reloads, 1);
  h.container.controller = h.next;
  h.container.dispatchEvent(new Event("controllerchange"));
  h.next.dispatchEvent(new Event("statechange"));
  mock.timers.tick(20000);
  assert.equal(h.reloads, 1);
  h.manager.dispose();
  mock.timers.reset();
});
test("timeout keeps an actionable state and resume detects late activation", async () => {
  mock.timers.enable({ apis: ["setTimeout", "setInterval"] });
  const h = harness();
  await h.manager.start("sw.js");
  h.manager.request();
  mock.timers.tick(12000);
  assert.equal(h.snapshot.phase, "stalled");
  assert.equal(h.reloads, 0);
  h.manager.request();
  assert.equal(h.next.messages, 2);
  mock.timers.tick(12000);
  h.activate(false);
  h.manager.resume();
  assert.equal(h.reloads, 1);
  h.manager.dispose();
  mock.timers.reset();
});
test("an already activated offered worker recovers on tap, but the old active worker never qualifies", async () => {
  const h = harness();
  await h.manager.start("sw.js");
  h.activate(false);
  h.manager.request();
  assert.equal(h.reloads, 1);
  h.manager.dispose();
  const stale = harness();
  await stale.manager.start("sw.js");
  stale.registration.waiting = null;
  stale.next.state = "redundant";
  stale.manager.request();
  assert.equal(stale.reloads, 0);
  assert.equal(stale.snapshot.phase, "error");
  stale.manager.dispose();
});
test("send failure and redundant activation recover through retry", async () => {
  const h = harness();
  await h.manager.start("sw.js");
  h.next.throws = true;
  h.manager.request();
  assert.equal(h.snapshot.phase, "error");
  h.next.throws = false;
  h.manager.request();
  assert.equal(h.snapshot.phase, "applying");
  h.next.state = "redundant";
  h.next.dispatchEvent(new Event("statechange"));
  assert.equal(h.snapshot.phase, "error");
  assert.equal(h.reloads, 0);
  h.manager.dispose();
});
test("the first worker claim never reloads and disposal cancels activation observers", async () => {
  const h = harness();
  h.container.controller = null;
  h.registration.waiting = null;
  await h.manager.start("sw.js");
  h.container.controller = h.old;
  h.container.dispatchEvent(new Event("controllerchange"));
  assert.equal(h.reloads, 0);
  h.registration.waiting = h.next;
  h.registration.dispatchEvent(new Event("updatefound"));
  h.manager.request();
  h.manager.dispose();
  h.activate();
  h.container.controller = h.next;
  h.container.dispatchEvent(new Event("controllerchange"));
  assert.equal(h.reloads, 0);
});

test("the initial cache installation never advertises an app update", async () => {
  const h = harness(false);
  h.registration.active = null;
  await h.manager.start("sw.js");
  assert.equal(h.snapshot.phase, "idle");
  h.activate(false);
  h.container.controller = h.next;
  h.container.dispatchEvent(new Event("controllerchange"));
  assert.equal(h.snapshot.phase, "idle");
  assert.equal(h.reloads, 0);
  h.manager.dispose();
});
"},{"path":"tests/app.spec.ts","content":"import { test, expect, type Page } from "@playwright/test";
import { prompts } from "../src/prompts";
async function openFolder(page: Page, id: string) {
  await page.locator(`[data-collection="${id}"]`).click();
}
test("directory first: three folders and no flat wall of prompts", async ({
  page,
}) => {
  await page.goto("/");
  await expect(page.locator(".collection-card")).toHaveCount(3);
  await expect(page.locator(".card")).toHaveCount(0);
  await openFolder(page, "companions");
  await expect(page.locator(".card")).toHaveCount(4);
  await expect(page).toHaveURL(/#collection\/companions$/);
  await page.goBack();
  await expect(page.locator(".collection-card")).toHaveCount(3);
  await expect(page.locator(".card")).toHaveCount(0);
  await openFolder(page, "materials");
  await expect(page.locator(".card")).toHaveCount(2);
});
test("each retained coach is reachable in exactly one collection", async ({
  page,
}) => {
  const seen: string[] = [];
  for (const [id, count] of [
    ["companions", 4],
    ["interaction", 3],
    ["materials", 2],
  ] as const) {
    await page.goto("/#library");
    await openFolder(page, id);
    await expect(page.locator(".card")).toHaveCount(count);
    const ids = await page
      .locator(".card .copy")
      .evaluateAll((es) => es.map((e) => e.getAttribute("data-copy")!));
    seen.push(...ids);
    for (const promptId of ids) {
      await page.locator(`.detail-link[data-detail="${promptId}"]`).click();
      await expect(page.locator("#prompt-text")).toHaveValue(
        prompts.find((p) => p.id === promptId)!.prompt,
      );
      await page.keyboard.press("Escape");
    }
  }
  expect(new Set(seen)).toEqual(new Set(prompts.map((p) => p.id)));
  expect(seen.length).toBe(9);
});
test("copy, favorites, global search and exact dialog payload", async ({
