"},{"path":"tests/cache-scopes.spec.ts","content":"import { test, expect } from "@playwright/test";
import { createServer, type Server } from "node:http";
import { readFile } from "node:fs/promises";
import { resolve, extname } from "node:path";

let server: Server;
let origin: string;
test.beforeAll(async () => {
  server = createServer(async (request, response) => {
    const pathname = new URL(request.url!, "http://localhost").pathname;
    const path = pathname.replace(/^\/(one|two)\//, "") || "index.html";
    const mime: Record<string, string> = { ".js": "application/javascript", ".html": "text/html", ".css": "text/css", ".webmanifest": "application/manifest+json", ".svg": "image/svg+xml", ".png": "image/png" };
    try {
      response.setHeader("Content-Type", mime[extname(path)] || "application/octet-stream");
      response.setHeader("Cache-Control", "no-store");
      response.end(await readFile(resolve("dist", path)));
    } catch { response.writeHead(404).end(); }
  });
  await new Promise<void>(done => server.listen(0, "127.0.0.1", done));
  const address = server.address();
  if (!address || typeof address === "string") throw Error("No test server");
  origin = "http://127.0.0.1:" + address.port;
});
test.afterAll(async () => {
  await new Promise<void>((done, reject) => server.close(error => error ? reject(error) : done()));
});

test("two deployed paths retain independent caches across activation and recovery", async ({ context, page }) => {
  const other = await context.newPage();
  const prefix = (path: string) => "talksprout-scope-" + encodeURIComponent(origin + path) + "-";
  await page.goto(origin + "/one/");
  await page.evaluate(() => navigator.serviceWorker.ready.then(() => true));
  await expect.poll(() => page.evaluate(() => caches.keys())).toContainEqual(expect.stringMatching(new RegExp("^" + prefix("/one/"))));
  await other.goto(origin + "/two/");
  await other.evaluate(() => navigator.serviceWorker.ready.then(() => true));
  const names = await page.evaluate(() => caches.keys());
  expect(names.some(name => name.startsWith(prefix("/one/")))).toBe(true);
  expect(names.some(name => name.startsWith(prefix("/two/")))).toBe(true);
  // Recovery must not delete the second installation, or ambiguous legacy data.
  await page.evaluate(() => caches.open("talksprout-legacy-fixture"));
  await page.goto(origin + "/one/recover.html");
  await page.locator("#reload").click();
  await page.waitForURL(url => url.pathname === "/one/");
  const afterRecovery = await other.evaluate(() => caches.keys());
  expect(afterRecovery.some(name => name.startsWith(prefix("/two/")))).toBe(true);
  expect(afterRecovery).toContain("talksprout-legacy-fixture");
  await context.setOffline(true);
  await other.reload();
  await expect(other.locator("#app")).not.toBeEmpty();
});
"},{"path":"tests/clipboard-writer.test.ts","content":"import { test } from "node:test";
import assert from "node:assert/strict";
import { createClipboardWriter } from "../src/clipboard-writer";

test("one writer serializes both libraries and starts the API synchronously", async () => {
  let finish!: () => void;
  const writes: string[] = [];
  const writer = createClipboardWriter((text) => { writes.push(text); return new Promise<void>((resolve) => { finish = resolve; }); }, () => "same");
  const first = writer.write({ text: "first" });
  assert.deepEqual(writes, ["first"]);
  assert.equal(await writer.write({ text: "second" }), false);
  finish();
  assert.equal(await first, true);
});
test("delivered data is recorded but stale feedback is suppressed after navigation or invalidation", async () => {
  let finish!: () => void;
  let context = "sheet-a";
  let delivered = 0;
  let feedback = 0;
  const writer = createClipboardWriter(() => new Promise<void>((resolve) => { finish = resolve; }), () => context);
  const pending = writer.write({ text: "payload", onDelivered: () => { delivered++; }, onSuccess: () => { feedback++; } });
  context = "sheet-b";
  finish();
  await pending;
  assert.equal(delivered, 1);
  assert.equal(feedback, 0);
  const next = writer.write({ text: "payload", onSuccess: () => { feedback++; } });
  writer.invalidate();
  finish();
  await next;
  assert.equal(feedback, 0);
});

test("asynchronous metadata completion keeps feedback current and the writer serialized", async () => {
  let finish!: () => void;
  let feedback = 0;
  const writer = createClipboardWriter(async () => {}, () => "same");
  const pending = writer.write({ text: "first", onDelivered: () => new Promise<void>(resolve => { finish = resolve; }), onSuccess: () => { feedback++; } });
  await Promise.resolve();
  assert.equal(await writer.write({ text: "second" }), false);
  writer.invalidate();
  finish();
  assert.equal(await pending, true);
  assert.equal(feedback, 0);
});
"},{"path":"tests/clipboard.spec.ts","content":"import { test, expect, type Page } from "@playwright/test";
import { prompts, reviewPrompts } from "../src/prompts";
import { promptText } from "../src/prompt-text";

declare global {
  interface Window {
    clipboardProbe: {
      writes: string[];
      resolve: (index: number) => void;
      reject: (index: number) => void;
    };
  }
}
async function settle(page: Page, index: number, success: boolean) {
  await page.evaluate(
    ({ index, success }) =>
      success
        ? window.clipboardProbe.resolve(index)
        : window.clipboardProbe.reject(index),
    { index, success },
  );
  await page.evaluate(
    () =>
      new Promise<void>((resolve) =>
        requestAnimationFrame(() => requestAnimationFrame(() => resolve())),
      ),
  );
}
test.beforeEach(async ({ page }) => {
  await page.addInitScript(() => {
    const callbacks: {
      resolve: () => void;
      reject: (reason: Error) => void;
    }[] = [];
    const writes: string[] = [];
    window.clipboardProbe = {
      writes,
      resolve: (index) => callbacks[index].resolve(),
      reject: (index) => callbacks[index].reject(Error("Clipboard denied")),
    };
    Object.defineProperty(navigator, "clipboard", {
      configurable: true,
      value: {
        writeText: (value: string) => {
          writes.push(value);
          return new Promise<void>((resolve, reject) =>
            callbacks.push({ resolve, reject }),
          );
        },
      },
    });
  });
});
test("late clipboard rejection cannot reverse navigation", async ({ page }) => {
  await page.goto("/#collection/companions");
  await page.locator('.copy[data-copy="daily-check-in"]').click();
  await page.getByRole("link", { name: "结束与复习", exact: true }).click();
  await settle(page, 0, false);
  await expect(page).toHaveURL(/#review$/);
  await expect(page.locator("#detail")).toHaveCount(0);
});
test("late rejection cannot reopen a dismissed sheet even after reopening the same prompt", async ({
  page,
}) => {
  await page.goto("/#collection/companions");
  await page.locator('.detail-link[data-detail="daily-check-in"]').click();
  await page.locator(".modal-copy").click();
  await page.keyboard.press("Escape");
  await expect(page).toHaveURL(/#collection\/companions$/);
  await page.locator('.detail-link[data-detail="daily-check-in"]').click();
  await settle(page, 0, false);
  await expect(page.getByRole("alert")).toHaveCount(0);
  await expect(page.locator(".modal-copy")).toHaveText("复制完整提示词");
});
test("a completed full copy cannot mark the spoken format copied", async ({
  page,
}) => {
  await page.goto("/#collection/companions");
  await page.locator('.detail-link[data-detail="daily-check-in"]').click();
  await page.locator(".modal-copy").click();
  await page.locator("#format-spoken").click();
  await settle(page, 0, true);
  await expect(page.locator(".modal-copy")).toHaveText("复制语音开场白");
  await page.locator(".modal-copy").click();
  await settle(page, 1, true);
  await expect(page.locator(".modal-copy")).toHaveText("已复制 ✓");
  expect(await page.evaluate(() => window.clipboardProbe.writes)).toEqual([
    prompts[0].prompt,
    prompts[0].spokenPrompt,
  ]);
});
test("a completed transcript copy cannot mark a different source copied", async ({
  page,
}) => {
  await page.goto("/#review");
  await page
    .locator('.detail-link[data-detail="complete-study-notes"]')
    .click();
  await page.locator("#review-source").selectOption("transcript");
  await page.locator(".modal-copy").click();
  await page.locator("#review-source").selectOption("current");
  await settle(page, 0, true);
  await expect(page.locator(".modal-copy")).toHaveText("复制完整提示词");
  expect(await page.evaluate(() => window.clipboardProbe.writes[0])).toBe(
    promptText(reviewPrompts[0], "full", "transcript"),
  );
});
test("one clipboard write at a time prevents out-of-order payloads", async ({
  page,
}) => {
  await page.goto("/#collection/companions");
  const first = page.locator('.copy[data-copy="daily-check-in"]');
  const second = page.locator('.copy[data-copy="gentle-start"]');
  await first.click();
  await expect(second).toBeDisabled();
  expect(await page.evaluate(() => window.clipboardProbe.writes.length)).toBe(
    1,
  );
  await settle(page, 0, true);
  await second.click();
  await settle(page, 1, true);
  expect(
    await page.evaluate(() =>
      JSON.parse(localStorage.getItem("talksprout:recent-items") || "[]").map((item: {promptId:string}) => item.promptId),
    ),
  ).toEqual(["gentle-start", "daily-check-in"]);
});
test("same-context clipboard failure retains the exact selected payload for manual copying", async ({
  page,
}) => {
  await page.goto("/#review");
  await page
    .locator('.detail-link[data-detail="vocabulary-ipa-review"]')
    .click();
  await page.locator("#format-spoken").click();
  await page.locator(".modal-copy").click();
  await settle(page, 0, false);
  await expect(page.getByRole("alert")).toContainText("手动复制");
  await expect(page.locator("#prompt-text")).toHaveValue(
    reviewPrompts.find((p) => p.id === "vocabulary-ipa-review")!.spokenPrompt,
  );
  await expect(page.locator("#prompt-text")).toBeFocused();
});
test("clipboard completion from a closed sheet does not change a new sheet", async ({
  page,
}) => {
  await page.goto("/#collection/companions");
  await page.locator('.detail-link[data-detail="daily-check-in"]').click();
  await page.locator(".modal-copy").click();
  await page.keyboard.press("Escape");
  await page.locator('.detail-link[data-detail="gentle-start"]').click();
  await settle(page, 0, true);
  await expect(page.locator("#dialog-title")).toHaveText("温柔引导纠正");
  await expect(page.locator(".modal-copy")).toHaveText("复制完整提示词");
});

test("an offline-cache warning never claims that a prompt was copied", async ({
  page,
}) => {
  await page.addInitScript(() => {
    Object.defineProperty(navigator.serviceWorker, "register", {
      configurable: true,
      value: () =>
        new Promise((_resolve, reject) => {
          (
            window as unknown as { rejectRegistration: () => void }
          ).rejectRegistration = () => reject(Error("Cache unavailable"));
        }),
    });
  });
  await page.goto("/#collection/companions");
  await page.locator('.detail-link[data-detail="daily-check-in"]').click();
  await page.evaluate(() =>
    (
      window as unknown as { rejectRegistration: () => void }
    ).rejectRegistration(),
  );
  await expect(page.locator('.sheet-footer [role="status"]')).toContainText(
    "离线缓存暂不可用",
  );
  await expect(page.locator(".modal-copy")).toHaveText("复制完整提示词");
  expect(await page.evaluate(() => window.clipboardProbe.writes.length)).toBe(
    0,
  );
});
