test('English suite renders 34 full/compact review and helper cases with 22 stable prompt IDs', () => {
  const cases = createEnglishCases();
  assert.equal(cases.length, 34);
  assert.equal(cases.filter(c => c.variant === 'spoken').length, 12);
  assert.equal(new Set(cases.map(c => c.id)).size, 34);
  assert.ok(cases.every(c => c.locale === 'en'));
  assert.equal(new Set(cases.map(c => c.promptId)).size, 22);
  assert.ok(cases.find(c => c.promptId === 'writing-intent')?.messages.at(-1)?.content.includes('周五'));
});

import { mkdtempSync, writeFileSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';

test('runner uses actual replies, reuses sealed cache, and rejects tampered cache (mock transport)', () => {
  const dir = mkdtempSync(join(tmpdir(), 'talksprout-session-'));
  try {
    // Local transport simulation, never a real provider execution.
    writeFileSync(join(dir, 'curl'), `#!/usr/bin/env python3
import json,sys
from pathlib import Path
args=sys.argv
body=json.loads(Path(args[args.index('--data-binary')+1][1:]).read_text())
messages=body['messages']
if body.get('response_format'):
    content=json.dumps({'verdicts':[{'id':'session-test','judgment':'pass','reason':'mock only'}]})
else:
    n=sum(m['role']=='assistant' for m in messages)
    assert all(m['content'].startswith('actual-') for m in messages if m['role']=='assistant')
    content='actual-'+str(n)
print(json.dumps({'id':'mock-'+str(len(messages)),'model':body['model'],'choices':[{'finish_reason':'stop','message':{'content':content}}]}))
print('200',end='')
`, { mode: 0o755 });
    const caseFile = join(dir, 'cases.json');
    const output = join(dir, 'output.json');
    writeFileSync(caseFile, JSON.stringify([{ ...createSessionCases()[0], id: 'session-test' }]));
    const run = (...flags: string[]) => spawnSync('python3', ['evals/live.py', '--cases', caseFile, '--output', output, ...flags], {
      env: { ...process.env, PATH: `${dir}:${process.env.PATH}`, OPENAI_API_KEY: 'local-mock-only' }, encoding: 'utf8',
    });
    let result = run();
    assert.equal(result.status, 0, result.stderr);
    const archive = JSON.parse(readFileSync(output, 'utf8'));
    assert.deepEqual(archive.cases[0].turnResults.map((t: {target: {content: string}}) => t.target.content), ['actual-0','actual-1','actual-2','actual-3']);
    assert.equal(archive.cases[0].executedMessages.filter((m: {role: string}) => m.role === 'assistant').length, 4);
    assert.equal(archive.sessionJudgeMethod, 'isolated-turn-prefix-v1');
    assert.equal(archive.cases[0].turnJudgments.length, 4);
    const original = archive.cases[0].target;
    result = run('--resume');
    assert.equal(result.status, 0, result.stderr);
    assert.deepEqual(JSON.parse(readFileSync(output, 'utf8')).cases[0].target, original);
    const revisedCase = { ...archive.cases[0].case, criterion: 'A revised judge criterion only; target inputs unchanged.' };
    writeFileSync(caseFile, JSON.stringify([revisedCase]));
    result = run('--resume');
    assert.equal(result.status, 0, result.stderr);
    const rejudged = JSON.parse(readFileSync(output, 'utf8'));
    assert.deepEqual(rejudged.targetReuseSummary, { reusedCases: 1, executedCases: 0 });
    assert.deepEqual(rejudged.cases[0].target, original);
    archive.cases[0].target.content = 'tampered';
    writeFileSync(output, JSON.stringify(archive));
    result = run('--resume');
    assert.equal(result.status, 0, result.stderr);
    assert.equal(JSON.parse(readFileSync(output, 'utf8')).cases[0].target.content, 'actual-3');
    result = run('--changed-from', output, '--report-only');
    assert.equal(result.status, 0, result.stderr);
    assert.equal(JSON.parse(result.stdout).selected, 0);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

import { validateLiveArchive } from '../evals/live-validate';
import { evidenceDigest } from '../evals/validate';
import policy from '../evals/live-policy.json';

test('refreshed per-row policy and snapshot cannot be swapped even with a new seal', () => {
  const initial = JSON.parse(readFileSync('evals/results/2026-11-14-optimization-initial.json', 'utf8'));
  const archived = initial.english.cases.find((r: {case: {promptId: string}}) => r.case.promptId === 'reading-guide');
  const expected = createEnglishCases().find(c => c.promptId === 'reading-guide')!;
  const row = { ...archived, case: expected, requestedModel: 'gpt-4.1-2025-04-14', judgePolicySha256: evidenceDigest({model:'gpt-4.1-2025-04-14', ...policy}) };
  row.evidenceSha256 = evidenceDigest(row);
  const archive = { ...initial.english, cases: [row], summary: {pass:1,fail:0,uncertain:0}, rawJudgeSummary: {pass:1,fail:0,uncertain:0} };
  assert.deepEqual(validateLiveArchive(archive, [expected]).issues, []);
  row.judgePolicySha256 = 'wrong';
  row.evidenceSha256 = evidenceDigest(row);
  assert.ok(validateLiveArchive(archive, [expected]).issues.some(i => i.includes('per-case judge policy')));
  row.judgePolicySha256 = evidenceDigest({model:row.requestedModel, ...policy});
  row.target = { ...row.target, model: 'another-snapshot' };
  row.evidenceSha256 = evidenceDigest(row);
  assert.ok(validateLiveArchive(archive, [expected]).issues.some(i => i.includes('snapshot mismatch')));
});

test('accepted session evidence requires the actual history and worst-turn gate after resealing', () => {
  const archive = JSON.parse(readFileSync('evals/fixtures/session-live-api.json', 'utf8'));
  assert.deepEqual(validateLiveArchive(archive, createSessionCases()).issues, []);
  const row = archive.cases[0];
  row.turnJudgments[0].judge.judgment = 'fail';
  row.evidenceSha256 = evidenceDigest(row);
  assert.ok(validateLiveArchive(archive, createSessionCases()).issues.some(i => i.includes('worst turn')));
  row.executedMessages[2].content = 'Authored replacement rather than the actual target reply';
  row.evidenceSha256 = evidenceDigest(row);
  assert.ok(validateLiveArchive(archive, createSessionCases()).issues.some(i => i.includes('actual target replies')));
});

test('each isolated turn uses a unique judge execution even after resealing', () => {
  const archive = JSON.parse(readFileSync('evals/fixtures/session-live-api.json', 'utf8'));
  archive.cases[0].turnJudgments[1].execution = archive.cases[0].turnJudgments[0].execution;
  archive.cases[0].evidenceSha256 = evidenceDigest(archive.cases[0]);
  assert.ok(validateLiveArchive(archive, createSessionCases()).issues.some(i => i.includes('unique across all turns')));
});
"},{"path":"tests/evals.test.ts","content":"import { test } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { allPrompts, prompts, reviewPrompts } from "../src/prompts";
import { promptText } from "../src/prompt-text";
import { evidenceDigest, suiteNames, validateArchive } from "../evals/validate";

type Case = Record<string, any>;
function seal(row: Case) {
  row.evidenceSha256 = evidenceDigest(row);
  return row;
}
function row(
  id: string,
  promptId: string,
  variant = "full",
  source = "current",
): Case {
  const prompt = allPrompts.find((p) => p.id === promptId)!;
  return seal({
    id,
    promptId,
    variant,
    source,
    promptSha256: createHash("sha256")
      .update(promptText(prompt, variant as "full", source as "current"))
      .digest("hex"),
    judgment: "pass",
    criterion: "Authored sample criterion",
    rationale: "Authored sample rationale",
    turns: [
      { role: "assistant", content: "Start" },
      { role: "user", content: "Practice" },
      { role: "assistant", content: "Response" },
    ],
  });
}
function valid() {
  const archives = Object.fromEntries(
    suiteNames.map((suite) => [suite, { scenarios: [] as Case[] }]),
  ) as Record<(typeof suiteNames)[number], { scenarios: Case[] }>;
  for (const suite of ["openings", "scenarios", "spoken"] as const)
    for (const p of prompts) {
      const r = row(
        `${suite}-${p.id}`,
        p.id,
        suite === "spoken" ? "spoken" : "full",
      );
      if (suite === "openings")
        r.turns = [{ role: "assistant", content: "Start" }];
      archives[suite].scenarios.push(seal(r));
    }
  for (const p of reviewPrompts)
    for (const variant of ["full", "spoken"])
      archives.review.scenarios.push(row(`${p.id}-${variant}`, p.id, variant));
  for (const id of ["transcript-isolation", "missing-transcript"]) {
    const r = row(id, reviewPrompts[0].id, "full", "transcript");
    r.inputConstruction = "Use the runtime template with the documented source";
    if (id === "transcript-isolation")
      r.transcript = "Learner: I live here.\nAI: Tell me more.";
    archives.review.scenarios.push(seal(r));
  }
  return archives;
}
test("valid synthetic archive and stable canonical evidence digest", () => {
  assert.deepEqual(validateArchive(valid()).issues, []);
  assert.equal(
    evidenceDigest({ b: { z: 1, a: 2 }, a: [1, 2] }),
    evidenceDigest({ a: [1, 2], b: { a: 2, z: 1 }, evidenceSha256: "ignored" }),
  );
  assert.notEqual(evidenceDigest({ a: [1, 2] }), evidenceDigest({ a: [2, 1] }));
});
const mutations: Record<string, (a: ReturnType<typeof valid>) => void> = {
  emptyTeaching: (a) => {
    a.scenarios.scenarios = [];
  },
  emptyResponseContent: (a) => {
    a.spoken.scenarios[0].turns[2].content = "";
  },
  reviewReplacesCoachOpening: (a) => {
    const r = row("replacement", reviewPrompts[0].id);
    r.turns = [{ role: "assistant", content: "Start" }];
    a.openings.scenarios[0] = r;
  },
  fullReplacesSpoken: (a) => {
    for (const r of a.spoken.scenarios) {
      r.variant = "full";
      r.promptSha256 = row("x", r.promptId).promptSha256;
    }
  },
  allPartial: (a) => {
    for (const s of suiteNames)
      for (const r of a[s].scenarios) r.judgment = "partial";
  },
  missingIsolation: (a) => {
    a.review.scenarios = a.review.scenarios.filter(
      (r) => r.id !== "transcript-isolation",
    );
  },
};
for (const [name, mutate] of Object.entries(mutations))
  test(`${name} is rejected before and after resealing`, () => {
    const a = valid();
    mutate(a);
    assert.ok(validateArchive(a).issues.length);
    for (const suite of suiteNames) a[suite].scenarios.forEach(seal);
    const issues = validateArchive(a).issues;
    assert.ok(
      issues.some((issue) => !issue.includes("evidence digest")),
      issues.join("\n"),
    );
  });
for (const field of [
  "transcript",
  "inputConstruction",
  "rationale",
  "judgment",
  "turns",
  "source",
])
  test(`evidence covers ${field}`, () => {
    const a = valid();
    const r = a.review.scenarios.find((r) => r.id === "transcript-isolation")!;
    if (field === "turns") r.turns[2].content = "Changed response";
    else r[field] = `${r[field]} changed`;
    assert.ok(
      validateArchive(a).issues.some((i) =>
        i.includes("stale evidence digest"),
      ),
    );
  });
for (const mutate of [
  (r: Case) => {
    r.variant = "garbage";
  },
  (r: Case) => {
    r.source = "garbage";
  },
  (r: Case) => {
    r.turns[1].role = "system";
  },
  (r: Case) => {
    r.turns[1].content = null;
  },
  (r: Case) => {
    r.learnerTurns = ["Wrong"];
  },
  (r: Case) => {
    r.assistantTurns = ["Wrong"];
  },
  (r: Case) => {
    r.turns.pop();
  },
])
  test("resealed malformed row is rejected", () => {
    const a = valid();
    const r = a.scenarios.scenarios[0];
    mutate(r);
    seal(r);
    assert.ok(validateArchive(a).issues.length);
  });
test("resealed transcript cases require distinct real and missing source evidence", () => {
  const a = valid();
  const isolation = a.review.scenarios.find(
    (r) => r.id === "transcript-isolation",
  )!;
  isolation.transcript =
    "[Paste the conversation here, including speaker labels]";
  seal(isolation);
  assert.ok(
    validateArchive(a).issues.some((i) =>
      i.includes("real labeled transcript"),
    ),
  );
  const missing = a.review.scenarios.find(
    (r) => r.id === "missing-transcript",
  )!;
  missing.transcript = "Learner: usable source";
  seal(missing);
  assert.ok(
    validateArchive(a).issues.some((i) => i.includes("must not supply")),
  );
});
test("duplicate IDs and duplicate prompt coverage are rejected even when sealed", () => {
  const a = valid();
  a.openings.scenarios[1] = structuredClone(a.openings.scenarios[0]);
  assert.ok(
    validateArchive(a).issues.some((i) => i.includes("duplicate case ID")),
  );
  a.openings.scenarios[1].id = "unique-id";
  seal(a.openings.scenarios[1]);
  assert.ok(
    validateArchive(a).issues.some((i) => i.includes("expected exactly one")),
  );
});
test("undefined duplicated fields and non-JSON evidence return issues without throwing", () => {
  for (const field of ["learnerTurns", "assistantTurns", "extra"]) {
    const a = valid();
    a.scenarios.scenarios[0][field] = undefined;
    assert.ok(
      validateArchive(a).issues.some((i) => i.includes("JSON values only")),
    );
  }
});
test("missing turn content and malformed duplicate arrays return issues without throwing", () => {
  const a = valid();
  const r = a.scenarios.scenarios[0];
  delete r.turns[1].content;
  r.learnerTurns = [null];
  seal(r);
  assert.ok(
    validateArchive(a).issues.some((i) =>
      i.includes("invalid turn role/content"),
    ),
  );
  assert.ok(
    validateArchive(a).issues.some((i) => i.includes("learnerTurns disagrees")),
  );
});
test("literal backslash-n does not substitute for transcript speaker lines", () => {
  const a = valid();
  const r = a.review.scenarios.find((r) => r.id === "transcript-isolation")!;
  r.transcript = "Learner: Hello.\\nAI: Hello.";
  seal(r);
  assert.ok(
    validateArchive(a).issues.some((i) =>
      i.includes("real labeled transcript"),
    ),
  );
});
