test("main views, prompt and settings sheets, and recovery have no detected AA violations", async ({
  page,
}) => {
  await page.goto("/");
  for (const stage of [
    "directory",
    "folder",
    "dialog",
    "settings",
    "instructions",
    "installation",
    "recovery",
