import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { createLiveCases } from "../evals/live-cases";
import { prompts, reviewPrompts } from "../src/prompts";
import { scenes, composeScene } from "../src/scenes";
import { promptText } from "../src/prompt-text";

test("live suite covers every scene and both formats without changing copied payloads", () => {
  const cases = createLiveCases();
  assert.equal(cases.length, new Set(cases.map((c) => c.id)).size);
  for (const scene of scenes)
    for (const variant of ["full", "spoken"]) {
      assert.ok(
        cases.some(
          (c) =>
            c.purpose === "scene-opening" &&
            c.selection?.sceneId === scene.id &&
            c.variant === variant,
        ),
      );
      if (scene.category === "interview")
        assert.ok(
          cases.some(
            (c) =>
              c.purpose === "mock-opening" &&
              c.selection?.sceneId === scene.id &&
              c.variant === variant &&
              c.selection.pace === "mock",
          ),
        );
    }
  for (const c of cases) {
    const p = [...prompts, ...reviewPrompts].find((p) => p.id === c.promptId)!;
    const payload = promptText(
      composeScene(p, c.selection),
      c.variant,
      c.source,
    );
    assert.equal(
      c.payloadSha256,
      createHash("sha256").update(payload).digest("hex"),
    );
    assert.ok(
      c.messages.every(
        (m) => ["user", "assistant"].includes(m.role) && m.content.trim(),
      ),
    );
    assert.ok(c.criterion.trim());
  }
});
test("live suite covers all coaches, review sources and retry detours", () => {
  const cases = createLiveCases();
  for (const p of prompts)
    for (const variant of ["full", "spoken"])
      for (const purpose of [
        "base-opening",
        "natural-answer",
        "help-before-attempt",
        "stop",
      ])
        assert.ok(
          cases.some(
            (c) =>
              c.promptId === p.id &&
              c.variant === variant &&
              c.purpose === purpose,
          ),
        );
  for (const p of reviewPrompts)
    for (const purpose of [
      "review-current",
      "review-missing",
      "voice-only-text-fallback",
      "review-transcript-isolation",
      "review-transcript-missing",
    ])
      assert.ok(
        cases.some((c) => c.promptId === p.id && c.purpose === purpose),
      );
  for (const c of cases.filter(
    (c) => c.purpose === "review-transcript-isolation",
  )) {
    assert.ok(c.messages.at(-1)!.content.includes("Learner: I live in Kyoto."));
    assert.ok(!c.messages.at(-1)!.content.includes("[Paste the conversation"));
  }
});
"},{"path":"tests/live-evals.test.ts","content":"import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import {
  validateLiveArchive,
  validateCompositionMatrix,
} from "../evals/live-validate";
import { recordedSceneIds } from "../evals/live-coverage";
import { createLiveCases } from "../evals/live-cases";
import { scenes } from "../src/scenes";
import { evidenceDigest } from "../evals/validate";
const archive = () =>
  JSON.parse(readFileSync("evals/fixtures/live-api.json", "utf8"));
test("recorded live executions and all composed payloads satisfy release coverage", () => {
  const live = validateLiveArchive(archive());
  assert.deepEqual(live.issues, []);
  assert.equal(live.cases, 562);
  assert.equal(live.adjudications, 4);
  const matrix = validateCompositionMatrix();
  assert.equal(matrix.combinations, 936);
  assert.equal(matrix.payloads, 1872);
  assert.deepEqual(matrix.issues, []);
});
test("a resealed response, missing case, or changed source cannot silently satisfy live evidence", () => {
  const changed = archive();
  changed.cases[0].target.content = "Changed response";
  assert.ok(
    validateLiveArchive(changed).issues.some((s) =>
      s.includes("stale live evidence"),
    ),
  );
  const missing = archive();
  missing.cases.pop();
  assert.ok(
    validateLiveArchive(missing).issues.some((s) => s.includes("missing")),
  );
  const input = archive();
  input.cases[0].case.messages[0].content += " Changed input";
  input.cases[0].evidenceSha256 = evidenceDigest(input.cases[0]);
  assert.ok(
    validateLiveArchive(input).issues.some((s) =>
      s.includes("stale or unexpected live input"),
    ),
  );
});
test("live validation rejects stale grading policy and missing API execution provenance", () => {
  const policy = archive();
  policy.judgePolicySha256 = "0".repeat(64);
  assert.ok(
    validateLiveArchive(policy).issues.some((s) =>
      s.includes("stale judge policy"),
    ),
  );
  const provenance = archive();
  delete provenance.cases[0].target.responseId;
  provenance.cases[0].evidenceSha256 = evidenceDigest(provenance.cases[0]);
  assert.ok(
    validateLiveArchive(provenance).issues.some((s) =>
      s.includes("real target execution"),
    ),
  );
});
test("semantic adjudication remains bound to raw target, input and judge records", () => {
  const tampered = archive();
  // A synthetic adjudication tests binding even when the release needs none.
  const row = tampered.cases[0];
  row.adjudication = {
    id: row.case.id,
    reviewer: "codex-semantic-review",
    judgment: "pass",
    releaseBlocking: false,
    reason: "Synthetic test review of the exact observed input, reply and original judge evidence.",
    rawJudge: { ...row.judge },
    observedReply: row.target.content,
    payloadSha256: row.case.payloadSha256,
    rawEvidenceSha256: evidenceDigest(row),
  };
  tampered.adjudications += 1;
  row.evidenceSha256 = evidenceDigest(row);
  assert.deepEqual(validateLiveArchive(tampered).issues, []);
  row.adjudication.observedReply = "Different reply";
  row.evidenceSha256 = evidenceDigest(row);
  assert.ok(
    validateLiveArchive(tampered).issues.some((s) =>
      s.includes("adjudication does not match"),
    ),
  );
  const counts = archive();
  counts.rawJudgeSummary.pass++;
  assert.ok(
    validateLiveArchive(counts).issues.some((s) =>
      s.includes("raw judge summary"),
    ),
  );
});

test("live coverage keeps the recorded scope fixed and reports new scenes as pending", () => {
  const live = validateLiveArchive(archive());
  assert.equal(recordedSceneIds.length, 160);
  assert.equal(new Set(recordedSceneIds).size, 160);
  assert.ok(Object.isFrozen(recordedSceneIds));
  assert.ok(recordedSceneIds.every((id) => scenes.some((scene) => scene.id === id)));
  assert.equal(live.recordedScenes, 160);
  assert.equal(live.pendingScenes, 0);
  assert.deepEqual(
    live.pendingSceneIds,
    scenes.filter((scene) => !recordedSceneIds.includes(scene.id)).map((scene) => scene.id),
  );
  const currentCases = createLiveCases();
  assert.equal(currentCases.length, 562);
  assert.equal(
    currentCases.filter((item) => item.selection && live.pendingSceneIds.includes(item.selection.sceneId)).length,
    0,
  );
  assert.deepEqual(live.issues, []);
});

test("removing a whole recorded scene cannot shrink the required live scope", () => {
  const missing = archive();
  const sceneId = recordedSceneIds[0];
  missing.cases = missing.cases.filter(
    (row: { case: { selection?: { sceneId: string } } }) => row.case.selection?.sceneId !== sceneId,
  );
  // Match aggregate counts to the shortened archive: scope must still reject it.
  missing.summary.pass = missing.cases.length;
  missing.rawJudgeSummary = { pass: 0, fail: 0, uncertain: 0 };
  for (const row of missing.cases) missing.rawJudgeSummary[row.judge.judgment]++;
  const issues = validateLiveArchive(missing).issues;
  assert.ok(issues.some((issue) => issue.startsWith("live: missing ") && issue.includes(`-full-${sceneId}-`)));
  assert.ok(issues.some((issue) => issue.startsWith("live: missing ") && issue.includes(`-spoken-${sceneId}-`)));
});

test("future catalog additions remain pending without weakening recorded coverage", () => {
  const before = validateLiveArchive(archive());
  const template = scenes.find((scene) => scene.category === "services")!;
  const probeId = "future-scene-probe";
  scenes.push({ ...template, id: probeId });
  try {
    const expanded = validateLiveArchive(archive());
    assert.equal(expanded.recordedScenes, before.recordedScenes);
    assert.equal(expanded.pendingScenes, before.pendingScenes + 1);
    assert.ok(expanded.pendingSceneIds.includes(probeId));
    assert.deepEqual(expanded.issues, []);
  } finally {
    assert.equal(scenes.pop()?.id, probeId);
  }
});


test("sealed judge records cannot reuse one execution across isolated cases", () => {
  const reused = archive();
  reused.cases[1].judgeExecution.responseId = reused.cases[0].judgeExecution.responseId;
  reused.cases[1].evidenceSha256 = evidenceDigest(reused.cases[1]);
  assert.ok(validateLiveArchive(reused).issues.some((issue) => issue.includes("must be isolated to one case")));
});
"},{"path":"tests/navigation.test.ts","content":"import { test } from "node:test";
import assert from "node:assert/strict";
import { readRoute } from "../src/navigation";
import { allPrompts } from "../src/prompts";

test("existing collection and review URLs retain their destination", () => {
  assert.deepEqual(readRoute("#collection/companions"), {
    page: "practice",
    collection: "companions",
    base: "#collection/companions",
    promptId: null,
    learningPromptId: null,
    infoId: null,
  });
  assert.equal(readRoute("#collection/materials").collection, "materials");
  assert.equal(readRoute("#collection/review").base, "#review");
  assert.equal(readRoute("#settings").page, "settings");
  assert.equal(readRoute("#unknown").base, "#library");
});
test("a prompt deep link opens only in the matching purpose", () => {
  for (const p of allPrompts) {
    const base = p.kind === "review" ? "#review" : "#library";
    assert.equal(readRoute(`${base}?prompt=${p.id}`).promptId, p.id);
    const wrong = p.kind === "review" ? "#library" : "#review";
    assert.equal(readRoute(`${wrong}?prompt=${p.id}`).promptId, null);
    assert.equal(readRoute(`#settings?prompt=${p.id}`).promptId, null);
  }
  assert.equal(readRoute("#review?prompt=missing").promptId, null);
});

test("settings sheets can be deep linked without leaking into practice routes", () => {
  assert.equal(readRoute("#settings?info=about").infoId, "about");
  assert.equal(readRoute("#settings?info=install").infoId, "install");
  assert.equal(readRoute("#library?info=about").infoId, null);
  assert.equal(readRoute("#settings?info=unknown").infoId, null);
});


test("supplementary links stay separate from coaches and reviews", () => {
  assert.equal(readRoute("#learning?prompt=writing-feedback").learningPromptId, "writing-feedback");
  assert.equal(readRoute("#learning?prompt=writing-feedback").promptId, null);
  for (const path of ["#library", "#review", "#settings", "#collection/materials"])
    assert.equal(readRoute(`${path}?prompt=writing-feedback`).learningPromptId, null);
  assert.equal(readRoute("#learning?prompt=daily-check-in").promptId, null);
  assert.equal(readRoute("#learning?prompt=missing").learningPromptId, null);
});

test("practice links restore compatible scenario without personal background", () => {
  const route = readRoute("#library?prompt=roleplay-coach&scene=technical-intro&pace=mock&format=spoken&background=secret");
  assert.deepEqual(route.sceneSelection, {sceneId:"technical-intro",pace:"mock",background:""});
  assert.equal(route.format, "spoken");
  assert.equal(readRoute("#library?prompt=daily-check-in&scene=technical-intro&pace=mock").sceneSelection?.pace, "coached");
  assert.equal(readRoute("#library?prompt=roleplay-coach&scene=missing").sceneSelection, undefined);
  assert.equal(readRoute("#settings?scene=technical-intro&format=spoken").format, undefined);
});
test("review options apply only to matching review prompts", () => {
  const review = allPrompts.find(p => p.kind === "review")!;
  const route = readRoute(`#review?prompt=${review.id}&source=transcript&format=spoken&scene=technical-intro`);
  assert.equal(route.reviewSource, "transcript");
  assert.equal(route.format, "spoken");
  assert.equal(route.sceneSelection, undefined);
  assert.equal(readRoute("#library?prompt=daily-check-in&source=transcript").reviewSource, undefined);
});

test("guide routes preserve article identity without opening prompt sheets", () => {
  const route = readRoute("#guides/ten-minute-ai-conversation?prompt=daily-check-in&scene=technical-intro");
  assert.equal(route.page, "guides");
  assert.equal(route.base, "#guides/ten-minute-ai-conversation");
  assert.equal((route as typeof route & { guideId?: string }).guideId, "ten-minute-ai-conversation");
  assert.equal(route.promptId, null);
  assert.equal(route.learningPromptId, null);
  assert.equal(route.sceneSelection, undefined);
  assert.equal(readRoute("#guides").page, "guides");
  assert.equal(readRoute("#guides/not-a-guide").page, "guides");
  assert.equal(readRoute("#guides-extra").page, "practice");
});

test("further resources retain a separate directory route without prompt parameters", () => {
  const route = readRoute("#guides?section=reading&prompt=daily-check-in");
  assert.equal(route.page, "guides");
  assert.equal(route.base, "#guides?section=reading");
  assert.equal(route.promptId, null);
  assert.equal(route.guideId, undefined);
  assert.equal(readRoute("#guides?section=unknown").base, "#guides");
});


test("companion and resource article identities remain distinct", () => {
  for (const id of ["four-strands-of-language-learning", "build-a-learning-routine", "self-talk-to-real-conversation", "ten-minute-ai-conversation", "english-resource-directory", "choose-learning-materials"])
    assert.equal(readRoute(`#guides/${id}`).guideId, id);
});
"},{"path":"tests/offline-check.test.ts","content":"import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createOfflineCheck } from '../src/offline-check';
import type { OfflineStatus } from '../src/offline-readiness';
const flush = async () => { for (let i = 0; i < 8; i++) await Promise.resolve(); };
function setup(read: () => Promise<OfflineStatus> = async () => 'unknown') {
  let visible = true;
  const timers = new Map<number, { callback: () => void; delay: number }>();
  let id = 0;
  let reads = 0;
  const statuses: OfflineStatus[] = [];
  const checker = createOfflineCheck({
    read: () => { reads++; return read(); },
    publish: status => statuses.push(status),
    visible: () => visible,
    schedule: (callback, delay) => { timers.set(++id, { callback, delay }); return id; },
    cancel: handle => { timers.delete(handle); },
  });
  return { checker, timers, statuses, reads: () => reads, hide: () => { visible = false; checker.suspend(); }, show: () => { visible = true; checker.resume(); }, tick: async () => {
    const next = timers.entries().next().value;
    assert.ok(next);
    timers.delete(next[0]); next[1].callback(); await flush();
  } };
}
test('unknown readiness gets five backoff retries and repeated resume does not reset the burst', async () => {
  const s = setup(); s.checker.resume(); await flush();
  for (const delay of [2000, 4000, 8000, 16000, 30000]) {
    s.checker.resume();
    assert.equal([...s.timers.values()][0]?.delay, delay);
    await s.tick();
  }
  assert.equal(s.reads(), 6); assert.equal(s.timers.size, 0);
  s.checker.resume(); await flush(); assert.equal(s.reads(), 7);
});
test('hidden checks pause and foreground starts a new bounded burst', async () => {
  const s = setup(async () => 'installing'); s.checker.resume(); await flush(); s.hide();
  assert.equal(s.timers.size, 0); s.checker.resume(); await flush(); assert.equal(s.reads(), 1);
  s.show(); await flush(); assert.equal(s.reads(), 2); assert.equal([...s.timers.values()][0]?.delay, 2000);
});
test('ready and unavailable stop retries', async () => {
  for (const status of ['ready', 'unavailable'] as const) {
    const s = setup(async () => status); s.checker.resume(); await flush();
    assert.deepEqual(s.statuses, [status]); assert.equal(s.timers.size, 0);
  }
});
test('lifecycle restart discards stale results and serializes disk reads', async () => {
  const resolves: ((s: OfflineStatus) => void)[] = [];
  const s = setup(() => new Promise(resolve => resolves.push(resolve)));
  s.checker.resume(); s.checker.restart(); assert.equal(s.reads(), 1);
  resolves[0]!('ready'); await flush(); assert.deepEqual(s.statuses, []); assert.equal(s.reads(), 2);
  resolves[1]!('installing'); await flush(); assert.deepEqual(s.statuses, ['installing']);
});
test('hidden or disposed in-flight reads cannot publish or schedule', async () => {
  for (const dispose of [false, true]) {
    let resolve!: (s: OfflineStatus) => void;
    const s = setup(() => new Promise(r => { resolve = r; })); s.checker.resume();
    if (dispose) s.checker.dispose(); else s.hide();
    resolve('ready'); await flush(); assert.deepEqual(s.statuses, []); assert.equal(s.timers.size, 0);
    if (dispose) { s.checker.restart(); await flush(); assert.equal(s.reads(), 1); }
  }
});
test('foreground waits for hidden in-flight work before starting fresh evidence', async () => {
  const resolves: ((s: OfflineStatus) => void)[] = [];
  const s = setup(() => new Promise(resolve => resolves.push(resolve)));
  s.checker.resume(); s.hide(); s.show(); assert.equal(s.reads(), 1);
  resolves[0]!('ready'); await flush(); assert.deepEqual(s.statuses, []); assert.equal(s.reads(), 2);
  resolves[1]!('ready'); await flush(); assert.deepEqual(s.statuses, ['ready']); assert.equal(s.timers.size, 0);
});
test('failed cache read reports unavailable without unhandled rejection or retries', async () => {
  const s = setup(async () => { throw Error('denied'); }); s.checker.resume(); await flush();
  assert.deepEqual(s.statuses, ['unavailable']); assert.equal(s.timers.size, 0);
});
"},{"path":"tests/offline-readiness.test.ts","content":"import { test } from 'node:test';
import assert from 'node:assert/strict';
import { getOfflineStatus } from '../src/offline-readiness';

test('registration success alone is not offline readiness', async () => {
  const storage = { keys: async () => [] } as unknown as CacheStorage;
  assert.equal(await getOfflineStatus(storage, 'https://app.test/a/', true), 'installing');
  assert.equal(await getOfflineStatus(storage, 'https://app.test/a/', false), 'unknown');
});
test('only a complete cache for this scope proves readiness', async () => {
  const scope = 'https://app.test/a/';
  let complete = true;
  const cache = { match: async (url: string) => url.endsWith('__offline_ready__') ? new Response(JSON.stringify([scope, scope + 'app.js'])) : complete ? new Response('cached') : undefined };
  const storage = { keys: async () => ['talksprout-scope-' + encodeURIComponent(scope) + '-v1'], open: async () => cache } as unknown as CacheStorage;
  assert.equal(await getOfflineStatus(storage, scope, false), 'ready');
  complete = false;
  assert.equal(await getOfflineStatus(storage, scope, false), 'unknown');
  assert.equal(await getOfflineStatus(storage, 'https://app.test/b/', false), 'unknown');
});
test('denied cache storage reports unavailable', async () => {
  const storage = { keys: async () => { throw Error('denied'); } } as unknown as CacheStorage;
  assert.equal(await getOfflineStatus(storage, 'https://app.test/', false), 'unavailable');
});
"},{"path":"tests/optimizations.spec.ts","content":"import { test, expect } from "@playwright/test";
import AxeBuilder from "@axe-core/playwright";

test("first practice guide, collection focus and independent learning favorites", async ({ page }) => {
  await page.goto("/");
  await expect(page.getByRole("region", { name: "第一次练习建议" })).toBeVisible();
  await page.getByRole("button", { name: "收起指引", exact: true }).click();
  await page.reload();
  await expect(page.getByRole("region", { name: "第一次练习建议" })).toHaveCount(0);
  await page.locator('[data-collection="companions"]').click();
  await page.getByRole("button", { name: "← 返回分类", exact: true }).click();
  await expect(page.locator('[data-collection="companions"]')).toBeFocused();
  await page.getByRole("button", { name: /听读写辅助/ }).click();
  await page.getByRole("button", { name: "收藏：视频与音频辅导", exact: true }).click();
  await page.getByRole("button", { name: "只看收藏", exact: true }).click();
  await expect(page.locator(".learning-prompt")).toHaveCount(1);
  await page.reload();
  await expect(page.getByRole("button", { name: "取消收藏：视频与音频辅导", exact: true })).toHaveAttribute("aria-pressed", "true");
});

test("saved scene combinations restore format and pace without retaining private background", async ({ page }) => {
  await page.goto("/#library?prompt=roleplay-coach&scene=project-deep-dive&pace=mock&format=spoken");
  await expect(page.getByRole("tab", { name: "语音开场白", exact: true })).toHaveAttribute("aria-selected", "true");
  await page.getByRole("button", { name: "保存常用组合", exact: true }).click();
  await page.getByRole("tab", { name: "完整提示词", exact: true }).click();
  await page.locator(".scene-settings summary").click();
  await page.locator("#scene-background").fill("PRIVATE_BACKGROUND_8364");
  await page.getByRole("button", { name: "保存常用组合", exact: true }).click();
  const saved = await page.evaluate(() => localStorage.getItem("talksprout:practice-shortcuts"));
  expect(saved).not.toContain("PRIVATE_BACKGROUND_8364");
  await page.keyboard.press("Escape");
  await expect(page.getByRole("region", { name: "常用练习组合" })).toBeVisible();
  await page.getByRole("button", { name: /情境扮演教练.*语音开场白/ }).click();
  await expect(page.getByRole("tab", { name: "语音开场白", exact: true })).toHaveAttribute("aria-selected", "true");
  await page.locator(".scene-settings summary").click();
  await expect(page.locator("#scene-background")).toHaveValue("");
  await expect(page.getByRole("button", { name: "模拟面试", exact: true })).toHaveAttribute("aria-pressed", "true");
});

test("English rendered learning/review prompts and visible recent entries", async ({ page }) => {
  await page.addInitScript(() => Object.defineProperty(navigator, "clipboard", { value: { writeText: () => Promise.resolve() } }));
  await page.goto("/#learning?prompt=writing-feedback");
  await expect(page.getByRole("dialog")).toBeVisible();
  await page.keyboard.press("Escape");
  await page.getByRole("button", { name: "English", exact: true }).click();
  await page.getByRole("button", { name: "Writing", exact: true }).click();
  await page.locator(".learning-prompt").filter({ hasText: "Writing feedback" }).click();
  await expect(page.locator("#prompt-text")).toHaveValue(/concise English explanations/);
  await page.getByRole("button", { name: "Copy prompt", exact: true }).click();
  await page.keyboard.press("Escape");
  await expect(page.getByRole("region", { name: "Recently copied", exact: true })).toBeVisible();
  expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
});

test("same-prompt URL removal resets options and multi-entry Back restores the collection opener", async ({ page }) => {
  await page.goto("/#library?prompt=roleplay-coach&scene=project-deep-dive&pace=mock&format=spoken");
  await expect(page.getByRole("tab", { name: "语音开场白", exact: true })).toHaveAttribute("aria-selected", "true");
  await page.evaluate(() => { location.hash = "#library?prompt=roleplay-coach"; });
  await expect(page.getByRole("tab", { name: "完整提示词", exact: true })).toHaveAttribute("aria-selected", "true");
  await expect(page.locator(".scene-trigger")).toContainText("不指定场景");
  await page.goto("/");
  await page.locator('[data-collection="companions"]').click();
  await page.locator('[data-detail="daily-check-in"]').click();
  await expect(page.getByRole("dialog")).toBeVisible();
  await page.evaluate(() => history.go(-2));
  await expect(page.getByRole("dialog")).toHaveCount(0);
  await expect(page.locator('[data-collection="companions"]')).toBeFocused();
});

test("manual fallback preserves the exact scene payload while shared links exclude background", async ({ page }) => {
  await page.addInitScript(() => Object.defineProperty(navigator, "clipboard", { value: { writeText: () => Promise.reject(Error("denied")) } }));
  await page.goto("/#library?prompt=roleplay-coach&scene=project-deep-dive&pace=mock");
  await expect(page.getByRole("dialog")).toBeVisible();
  await page.locator(".scene-settings summary").click();
  await page.locator("#scene-background").fill("PRIVATE_BACKGROUND_468");
  const payload = await page.locator("#prompt-text").inputValue();
  await page.getByRole("button", { name: "复制完整提示词", exact: true }).click();
  await expect(page.locator("#prompt-text")).toHaveValue(payload);
  await expect(page.locator("#prompt-text")).toBeFocused();
  await page.getByText("分享练习链接", { exact: true }).click();
  const link = await page.locator("#practice-link").inputValue();
  expect(link).toContain("scene=project-deep-dive");
  expect(link).toContain("pace=mock");
  expect(link).not.toContain("PRIVATE_BACKGROUND_468");
});
