        expect(
          await page
            .locator("dialog")
            .evaluate((e) => e.scrollWidth <= e.clientWidth),
        ).toBe(true);
      const scan = await new AxeBuilder({ page })
        .withTags(["wcag2a", "wcag2aa", "wcag21aa"])
        .analyze();
      expect(
        scan.violations.map((v) => ({ id: v.id, nodes: v.nodes.length })),
        `${language} ${state}`,
      ).toEqual([]);
    }
    await page.keyboard.press("Escape");
  }
});
